// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `10 create forecast.solar url.js` and the embedded `func` for "create forecast.solar url"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Builds the forecast.solar API endpoint URL from node environment variables.
// - Supports optional API key for authenticated (higher rate-limit) requests.
// Env vars used:
// - `apikey` (optional) -> if set, injected into URL path for authenticated access
// - `type`              -> endpoint type (e.g. `estimate`)
// Input:
// - msg (any) -> triggers URL construction
// Output (1):
// - output 1 -> msg with msg.url set to the constructed forecast.solar endpoint
// Change notes:
// 1. Initial version.
// ==========================
msg.url = 'https://api.forecast.solar/';

if (env.get('apikey')) {
    msg.url += env.get('apikey') + '/';
    }

msg.url += env.get('type') + '/';

msg.url += env.get('watt') + '/';

msg.url += env.get('latitude') + '/' +
           env.get('longitude') + '/' +
           env.get('declination') + '/' +
           env.get('azimuth') + '/' +
           env.get('modules power');

msg.topic = 'solar forecast: '+(env.get('type') || '');
msg.topic += (' '+env.get('watt') || '');
if (env.get('kwhoutput')) {
    msg.topic += ' (kWh)';
}
return msg;

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `12 update ratelimit.js` and the embedded `func` for "update ratelimit"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Reads the rate-limit data from the forecast.solar API response and stores it
//   into flow context for monitoring and status display.
// Input:
// - msg.payload.message.ratelimit : { remaining, limit }
// Flow context write:
// - `forecast.solar.ratelimit.remaining`
// - `forecast.solar.ratelimit.limit`
// Output (1):
// - output 1 -> msg pass-through
// Change notes:
// 1. Initial version.
// ==========================
var remaining = msg.payload.message.ratelimit.remaining || 0;
var limit = msg.payload.message.ratelimit.limit;

flow.set('forecast.solar.ratelimit.remaining', remaining)
flow.set('forecast.solar.ratelimit.limit', limit)

return msg;

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `13 update status.js` and the embedded `func` for "update status"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Reads remaining / limit from flow context and shows a colour-coded rate-limit
//   status badge on the node (green = ok, yellow = low, red = exhausted).
// Flow context read:
// - `forecast.solar.ratelimit.remaining`
// - `forecast.solar.ratelimit.limit`
// Input:
// - msg (any) -> triggers a status refresh
// Output (1):
// - output 1 -> msg pass-through
// Change notes:
// 1. Initial version.
// ==========================
var remaining = flow.get('forecast.solar.ratelimit.remaining') || -1;
var limit = flow.get('forecast.solar.ratelimit.limit') || -1

var text = remaining.toString() + '/' + limit.toString();
var fill = "green";

if (remaining == 0) {
    fill = "red";
    text = "Limit used";
}

if (remaining > 0 && remaining < limit / 2) {
    fill = "yellow"
}

if (remaining == -1 ) {
    fill = "blue"
    text = "Limits unknown"
}

msg.payload = ({ fill: fill, text: text });

return msg;

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `21 Create graph output.js` and the embedded `func` for "Create graph output"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Transforms the normalised forecast.solar hourly data into a chart.js / ui_chart
//   payload with labels, series names, and two-dimensional data arrays.
// Input:
// - msg.payload : normalised hourly forecast data (output of "Processed info" / "Adjust solar forecast for shade")
// Output (1):
// - output 1 -> msg.payload = [{ labels: [...], series: [...], data: [[...], ...] }]
//   for consumption by a Node-RED ui_chart node
// Change notes:
// 1. Initial version.
// ==========================
var m = {};
m.labels = [];
m.data = [];

m.series = [];
m.data = [];
m.labels = [];

for (let j = 0; j <= msg.days; j++) {
    m.data[j] = [];
}

if (msg.watt === 'watt_hours_day') {
    var i = 0;
    m.series.push("Watt hours per day");
    for (const key in msg.payload.result) {
        m.labels.push(key);
        if (msg.kwhoutput) {
            m.data[i] = +(Math.round(msg.payload.result[key]/100)*.1).toFixed(1);
        } else {
            m.data[i] = msg.payload.result[key];
        }
        i++;
    }
    m.data = [m.data];
    return { payload: [m] };
}

for (let i = 0; i <= 23; i++) {

    m.labels.push(i.toString()+':00');
    if (msg.resolution === 4) {
       m.labels.push(i.toString()+':15');
    }
    if (msg.resolution === 2 || msg.resolution == 4) {
       m.labels.push(i.toString()+':30');
    }
    if (msg.resolution === 4) {
       m.labels.push(i.toString()+':45');
    }

    for (let j = 0; j <= msg.days; j++) {
        m.data[j].push(0);
        if (msg.resolution === 4) {
           m.data[j].push(0)
        }
        if (msg.resolution === 2 || msg.resolution == 4) {
           m.data[j].push(0)
        }
        if (msg.resolution === 4) {
           m.data[j].push(0)
        }

    }
}

var offset = 0;
for (const key in msg.payload.result) {
    var d = new Date(key)
    if (m.series.indexOf(d.toISOString().split('T')[0]) === -1) {
        m.series.push(d.toISOString().split('T')[0])
    }

    var h = d.getHours();
    var minutes = d.getMinutes();

    if (minutes === 0 ) {
        offset = 0;
    } else {
        offset++;
    }

    if (msg.kwhoutput) {
        m.data[m.series.length - 1][h*msg.resolution+offset] = +(Math.round(msg.payload.result[key]/100)*.1).toFixed(1);
    } else {
        m.data[m.series.length - 1][h*msg.resolution+offset] = msg.payload.result[key];
    }
}

return { payload: [m] };

