// Sync rule:
// - `19 Format hourly energy line.js` and the embedded `func` for "Format hourly energy line"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Formats a completed hourly energy record as one CSV row of the monthly energy file and
//   builds the shell command that appends it (the header is written when the file is new).
// Input:
// - msg.payload : { hourKey: 'YYYY-MM-DD HH', gridWh, acWh, solarWh,
//                   billWh, peakW, setpointW, season: 'S' | 'W', coverageMin }
// Output (1):
// - output 1 -> exec "Append energy CSV" (`sh -c <payload>`), msg.filename = the CSV path
// File:
// - /data/home/nodered/grid-control-logs/energy-YYYY-MM.csv
//     hour,grid_wh,ac_wh,sol_wh,bill_wh,peak_w,setpoint_w,season,min
//     2026-10-17 22,2450,2432,0,1715,2610,6440,W,60
//   bill_wh  = grid Wh as counted for the capacity tariff (night hours x night billing %)
//   peak_w   = highest grid import W seen in the hour
//   setpoint_w / season = the season plan for that hour
//   min      = minutes of the hour actually integrated (60 = full hour; less after a restart)
// Change notes:
// 1. Initial version.
// 2. Added Sol column: PV charger generation Wh accumulated from `/Dc/Pv/Power`.
// 3. Switched from the daily `energy-YYYY-MM-DD.log` text file to the monthly CSV with tariff columns.
//    Legacy daily files are kept untouched and are still read by the dashboard and the controller.
// ==========================
if (!msg.payload || !msg.payload.hourKey) return null;

const LOG_DIR = '/data/home/nodered/grid-control-logs';
const HEADER = 'hour,grid_wh,ac_wh,sol_wh,bill_wh,peak_w,setpoint_w,season,min';
const p = msg.payload;
const int = value => Math.round(Number(value) || 0);
const season = p.season === 'W' || p.season === 'S' ? p.season : '';
const row = [
    String(p.hourKey).substring(0, 13),
    int(p.gridWh),
    int(p.acWh),
    int(p.solarWh),
    int(p.billWh),
    int(p.peakW),
    int(p.setpointW),
    season,
    p.coverageMin === undefined ? '' : int(p.coverageMin)
].join(',');
const filename = LOG_DIR + '/energy-' + String(p.hourKey).substring(0, 7) + '.csv';
// Only digits, dates, commas and S/W reach the script, so plain single quotes are safe.
const script = 'mkdir -p "' + LOG_DIR + '"; f="' + filename + '"; [ -s "$f" ] || echo "' + HEADER + '" > "$f"; echo "' + row + '" >> "$f"';

msg.filename = filename;
msg.csvRow = row;
msg.payload = "'" + script + "'";
return msg;

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `17 Update daily summary.js` and the embedded `func` for "Update daily summary"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Receives a completed hourly energy record and appends or updates it in the
//   flow context `dailySummary` for today's date.
// - Automatically resets the summary when the date rolls over to a new day.
// - Output 1 (file write) is kept in the signature but no longer used.
// Input:
// - msg.payload : { hourKey: 'YYYY-MM-DD HH', gridWh: number, acWh: number, solarWh: number }
// Flow context write:
// - `dailySummary` -> { dateKey: 'YYYY-MM-DD', hours: [{ hour, gridWh, acWh, solarWh }, …] }
// Output (1):
// - output 1 -> msg with the updated daily summary payload
// Change notes:
// 1. Initial version.
// 2. Added solarWh field: accumulated PV charger generation Wh per hour (from `/Dc/Pv/Power`).
// 3. No longer writes `summary-YYYY-MM-DD.log`: the monthly `energy-YYYY-MM.csv` holds the same
//    hourly rows (output 1 is always null). Existing summary files are kept and still readable.
// ==========================
if (!msg.payload || !msg.payload.hourKey) return null;
const { hourKey, gridWh, acWh } = msg.payload;
const solarWh = Number(msg.payload.solarWh) || 0;
const dateKey = hourKey.substring(0, 10);
const hourLabel = hourKey.substring(11, 13) + ':00';

let summary = flow.get('dailySummary') || { dateKey: '', hours: [] };
if (summary.dateKey !== dateKey) {
    summary = { dateKey, hours: [] };
}
summary.hours = summary.hours.filter(h => h.hour !== hourLabel);
summary.hours.push({ hour: hourLabel, gridWh, acWh, solarWh });
summary.hours.sort((a, b) => a.hour.localeCompare(b.hour));
flow.set('dailySummary', summary);

const totalGrid = summary.hours.reduce((s, h) => s + h.gridWh, 0);
const totalAc = summary.hours.reduce((s, h) => s + h.acWh, 0);
const chart = {
    labels: summary.hours.map(h => h.hour),
    series: ['Grid Wh', 'AC Wh', 'Solar Wh'],
    data: [
        summary.hours.map(h => h.gridWh),
        summary.hours.map(h => h.acWh),
        summary.hours.map(h => h.solarWh || 0)
    ]
};

const dashboardMsg = {
    topic: 'hourly-load-stats',
    payload: [chart],
    summary: {
        dateKey,
        totalGrid,
        totalAc,
        hours: summary.hours
    }
};

return [null, dashboardMsg];

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `14 Build dashboard hourly widgets.js` and the embedded `func` for "Build dashboard hourly widgets"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Reads today's completed hourly energy rows (dailySummary) and the live partial hour
//   (dashboardLiveHour) from flow context, then builds the hourly widget payload for the dashboard.
// Flow context read:
// - `dailySummary`      -> completed hourly energy rows for today
// - `dashboardLiveHour` -> live (partial) current-hour Wh accumulators
// Input:
// - msg (any) -> triggers a rebuild from flow context
// Output (1):
// - output 1 -> dashboard hourly widget payload array
// Change notes:
// 1. Initial version.
// 2. Added Sol Wh column: parses optional '| Sol NWh' from energy/summary log files;
//    carries solarWh per row; adds Solar Wh chart series; shows solar in summary and live text.
// 3. Also parses rows of the monthly `energy-YYYY-MM.csv` (`YYYY-MM-DD HH,grid,ac,sol,...`).
// ==========================
function todayKeyFromDate(date) {
    return [
        date.getFullYear(),
        String(date.getMonth() + 1).padStart(2, '0'),
        String(date.getDate()).padStart(2, '0')
    ].join('-');
}

function buildEmptySummary(dateKey) {
    const hours = [];

    for (let index = 0; index < 24; index += 1) {
        hours.push({
            hour: String(index).padStart(2, '0') + ':00',
            gridWh: 0,
            acWh: 0,
            solarWh: 0,
            status: 'pending'
        });
    }

    return {
        dateKey,
        hours,
        totalGrid: 0,
        totalAc: 0,
        totalSolar: 0,
        availableHours: 0
    };
}

function parseSummaryText(rawText, dateKey) {
    const summary = buildEmptySummary(dateKey);
    const rowsByHour = {};

    if (typeof rawText === 'string' && rawText.trim()) {
        rawText.split(/\r?\n/).forEach(line => {
            const trimmed = line.trim();
            const legacyMatch = trimmed.match(/^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}) \| Grid ([-]?\d+)Wh \| AC ([-]?\d+)Wh(?:\s*\|\s*Sol\s*([-]?\d+)Wh)?/);
            const csvMatch = legacyMatch ? null : trimmed.match(/^(\d{4}-\d{2}-\d{2}) (\d{2}),([-]?\d+),([-]?\d+),([-]?\d+)/);
            const match = legacyMatch || (csvMatch ? [csvMatch[0], csvMatch[1], csvMatch[2] + ':00', csvMatch[3], csvMatch[4], csvMatch[5]] : null);

            if (!match || match[1] !== dateKey) {
                return;
            }

            rowsByHour[match[2]] = {
                hour: match[2],
                gridWh: Number(match[3]) || 0,
                acWh: Number(match[4]) || 0,
                solarWh: Number(match[5]) || 0,
                status: 'done'
            };
        });
    }

    summary.hours = summary.hours.map(row => rowsByHour[row.hour] || row);
    summary.availableHours = summary.hours.filter(row => row.status === 'done').length;
    summary.totalGrid = summary.hours.reduce((sum, row) => sum + (row.status === 'done' ? row.gridWh : 0), 0);
    summary.totalAc = summary.hours.reduce((sum, row) => sum + (row.status === 'done' ? row.acWh : 0), 0);
    summary.totalSolar = summary.hours.reduce((sum, row) => sum + (row.status === 'done' ? (row.solarWh || 0) : 0), 0);
    return summary;
}

function byteSize(rawText) {
    if (typeof rawText !== 'string' || !rawText.length) {
        return 0;
    }

    return typeof Buffer !== 'undefined'
        ? Buffer.byteLength(rawText, 'utf8')
        : rawText.length;
}

if (msg.topic === 'controller-trace' && msg.payload && msg.payload.hourBudget) {
    flow.set('dashboardLiveHour', {
        timestamp: msg.payload.timestamp || '',
        hourKey: msg.payload.hourBudget.hourKey || '',
        gridWh: Number(msg.payload.hourBudget.usedWh) || 0,
        acWh: Number(msg.payload.acLoadBudget && msg.payload.acLoadBudget.usedWh) || 0,
        solarWh: Number(msg.payload.solarBudget && msg.payload.solarBudget.usedWh) || 0,
        gridPowerW: Number(msg.payload.storedGridPowerW) || 0,
        acPowerW: Number(msg.payload.storedAcLoadPowerW) || 0
    });
}

const todayKey = todayKeyFromDate(new Date());
const selectedDate = flow.get('dashboardSelectedDate') || todayKey;
const summaryFileName = '/data/home/nodered/grid-control-logs/summary-' + selectedDate + '.log';
const energyFileName = '/data/home/nodered/grid-control-logs/energy-' + selectedDate + '.log';
const selectedFileName = summaryFileName + ' | fallback ' + energyFileName + ' | energy-' + selectedDate.substring(0, 7) + '.csv';

if (msg.topic === 'selected-day-summary-loading') {
    flow.set('dashboardSelectedRawFile', {
        dateKey: msg.dateKey || selectedDate,
        fileName: selectedFileName,
        rawText: '',
        status: 'loading',
        fileSize: 0
    });
}

if (msg.topic === 'selected-day-summary-file') {
    const rawFileText = typeof msg.payload === 'string' ? msg.payload : '';
    const parsedSummary = parseSummaryText(rawFileText, msg.dateKey || selectedDate);
    flow.set('dashboardSelectedSummary', parsedSummary);
    flow.set('dashboardSelectedRawFile', {
        dateKey: msg.dateKey || selectedDate,
        fileName: selectedFileName,
        rawText: rawFileText,
        status: rawFileText.trim() ? 'loaded' : 'empty',
        fileSize: byteSize(rawFileText)
    });
}

let summary = flow.get('dashboardSelectedSummary');
if (!summary || summary.dateKey !== selectedDate) {
    summary = parseSummaryText('', selectedDate);
    flow.set('dashboardSelectedSummary', summary);
}

const rawFileState = flow.get('dashboardSelectedRawFile') || {
    dateKey: selectedDate,
    fileName: selectedFileName,
    rawText: '',
    status: 'idle',
    fileSize: 0
};
const rows = Array.isArray(summary.hours)
    ? summary.hours.map(row => ({ ...row }))
    : buildEmptySummary(selectedDate).hours;
const live = flow.get('dashboardLiveHour') || null;
const isToday = selectedDate === todayKey;
let displayGridTotal = Number(summary.totalGrid) || 0;
let displayAcTotal = Number(summary.totalAc) || 0;
let displaySolarTotal = Number(summary.totalSolar) || 0;
let liveText = 'Selected day loaded from file';

if (isToday && live && live.hourKey && live.hourKey.substring(0, 10) === selectedDate) {
    const liveHourLabel = live.hourKey.substring(11, 13) + ':00';
    const liveRow = rows.find(row => row.hour === liveHourLabel);

    if (liveRow) {
        liveRow.gridWh = Math.round(live.gridWh);
        liveRow.acWh = Math.round(live.acWh);
        liveRow.solarWh = Math.round(live.solarWh || 0);
        liveRow.status = 'live';
    }

    displayGridTotal += Math.round(live.gridWh);
    displayAcTotal += Math.round(live.acWh);
    displaySolarTotal += Math.round(live.solarWh || 0);
    liveText = 'Live ' + liveHourLabel + ' | Grid ' + Math.round(live.gridWh) + 'Wh @ ' + Math.round(live.gridPowerW) + 'W | AC ' + Math.round(live.acWh) + 'Wh @ ' + Math.round(live.acPowerW) + 'W | Sol ' + Math.round(live.solarWh || 0) + 'Wh';
}
else if (summary.availableHours === 0) {
    liveText = 'No saved hourly file data for ' + selectedDate;
}

const chart = {
    labels: rows.map(row => row.hour),
    series: ['Grid Wh', 'AC Wh', 'Solar Wh'],
    data: [
        rows.map(row => row.gridWh),
        rows.map(row => row.acWh),
        rows.map(row => row.solarWh || 0)
    ]
};

const summaryText = selectedDate + ' | Hours ' + summary.availableHours + '/24 | Grid ' + displayGridTotal + 'Wh | AC ' + displayAcTotal + 'Wh | Sol ' + displaySolarTotal + 'Wh';

return [
    { topic: 'hourly-load-stats', payload: [chart] },
    { payload: summaryText },
    { payload: liveText },
    { payload: { dateKey: selectedDate, rows, isToday, availableHours: summary.availableHours, fileName: selectedFileName } },
    { payload: { dateKey: selectedDate, fileName: selectedFileName, rawText: rawFileState.dateKey === selectedDate ? rawFileState.rawText : '', status: rawFileState.dateKey === selectedDate ? rawFileState.status : 'idle', fileSize: rawFileState.dateKey === selectedDate ? rawFileState.fileSize : 0 } }
];

