        updatedAt: current.updatedAt || '',
        level: status.level || 'info',
        protectionStatus: protectionStatusLabel,
        forceChargeStatus: forceChargeStatusLabel,
        currentChargingPowerW,
        gridSupportW: Math.max(0, Math.round(Number(current.gridSupportW) || 0)),
        gridSupportMode,
        adaptiveGridSupportW,
        plannedGridSupportW,
        gridSupportLowSunBlocked: Boolean(trace && trace.gridSupportLowSunBlocked),
        exportGuardStatus: exportGuardStatusLabel,
        exportGuardActive,
        exportGuardBoostW,
        gridPowerSignedW,
        solarGenerationW: Math.max(0, Math.round(Number(trace && trace.solarGenerationW) || 0)),
        remainingForecastAh: Number.isFinite(remainingForecastAh) ? remainingForecastAh.toFixed(1) : '0.0',
        batteryRemainingAh: Number.isFinite(batteryRemainingAh) ? batteryRemainingAh.toFixed(1) : 'n/a',
        forceChargeGridW,
        message: status.message || 'Use Save to persist protection changes.'
    }
};

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `05 Save HV settings from dashboard.js` and the embedded `func` for "Save HV settings from dashboard"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Validates and persists high-voltage protection settings submitted from the dashboard.
// - Rejects invalid values; sends an error status on validation failure.
// Config file:
// - /data/home/nodered/grid-control-config/high-voltage-settings.json
// Input:
// - msg.payload : form object with fields:
//   enabled, start, release, full (V), gridSupportW (W), forceChargeEnabled, forceChargeGridW (W)
//   gridSupportMode, gridSupportBatteryCapacityAh, gridSupportReserveAh,
//   gridSupportStartHour, gridSupportEndHour, gridSupportMaxDischargeA,
//   gridSupportForecastConfidencePct, gridSupportSolarAssistGainPct,
//   gridSupportWeakForecastBlockAh, gridSupportMinGridImportW,
//   gridSupportDisableNoSun, gridSupportDisableNoSunBelowW, exportGuardEnabled,
//   forceChargeLimiterEnabled, forceChargeLimiterStart (V), forceChargeLimiterRelease (V), forceChargeLimiterFull (V)
// Validation limits:
// - HV voltage: 50–60 V; required: full > start >= release
// - gridSupportW: 0–1000 W;  forceChargeGridW: 0–3000 W
// - adaptive support: battery capacity 0–2000 Ah, reserve 0–1000 Ah, hours 0–23,
//   max discharge 0–50 A, confidence/gain 0–100 %, min grid import 200–1000 W,
//   low-sun threshold 0–5000 W
// - FC limiter voltage: 40–60 V; required: release > start > full
// Output (1):
// - output 1 -> success confirmation payload after saving
// Change notes:
// 1. Initial version.
// 2. Added forceChargeLimiterEnabled/Start/Release/Full: voltage-based activation for AC Force Charging.
// 3. Added exportGuardEnabled: block grid export by letting the battery absorb the surplus.
// ==========================
const CONFIG_PATH = '/data/home/nodered/grid-control-config/high-voltage-settings.json';
const GRID_SUPPORT_MODE_HV_ONLY = 'hv-only';
const GRID_SUPPORT_MODE_ADAPTIVE_DAY = 'adaptive-day';
const GRID_SUPPORT_MODE_HYBRID = 'hybrid';
const MIN_SETTING = 50;
const MAX_SETTING = 60;
const MIN_GRID_SUPPORT_W = 0;
const MAX_GRID_SUPPORT_W = 1000;
const MIN_GRID_SUPPORT_BATTERY_CAPACITY_AH = 0;
const MAX_GRID_SUPPORT_BATTERY_CAPACITY_AH = 2000;
const MIN_GRID_SUPPORT_RESERVE_AH = 0;
const MAX_GRID_SUPPORT_RESERVE_AH = 1000;
const MIN_GRID_SUPPORT_HOUR = 0;
const MAX_GRID_SUPPORT_HOUR = 23;
const MIN_GRID_SUPPORT_MAX_DISCHARGE_A = 0;
const MAX_GRID_SUPPORT_MAX_DISCHARGE_A = 50;
const MIN_GRID_SUPPORT_PCT = 0;
const MAX_GRID_SUPPORT_PCT = 100;
const MIN_GRID_SUPPORT_WEAK_FORECAST_AH = 0;
const MAX_GRID_SUPPORT_WEAK_FORECAST_AH = 500;
const MIN_GRID_SUPPORT_MIN_GRID_IMPORT_W = 200;
const MAX_GRID_SUPPORT_MIN_GRID_IMPORT_W = 1000;
const MIN_GRID_SUPPORT_DISABLE_NO_SUN_BELOW_W = 0;
const MAX_GRID_SUPPORT_DISABLE_NO_SUN_BELOW_W = 5000;
const MIN_FORCE_CHARGE_W = 0;
const MAX_FORCE_CHARGE_W = 3000;
const MIN_FC_LIMITER = 40;
const MAX_FC_LIMITER = 60;

function normalizeGridSupportMode(value) {
    const normalized = String(value || '').toLowerCase();

    if (normalized === GRID_SUPPORT_MODE_ADAPTIVE_DAY || normalized === GRID_SUPPORT_MODE_HYBRID) {
        return normalized;
    }

    return GRID_SUPPORT_MODE_HV_ONLY;
}

function clampRounded(value, min, max) {
    return Math.min(Math.max(Math.round(Number(value) || 0), min), max);
}

function normalizeSettings(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }

    const enabled = Boolean(value.enabled);
    const start = Number(value.start);
    const release = Number(value.release);
    const full = Number(value.full);
    const rawGridSupportW = Number(value.gridSupportW);
    const gridSupportMode = normalizeGridSupportMode(value.gridSupportMode);
    const gridSupportBatteryCapacityAh = clampRounded(value.gridSupportBatteryCapacityAh, MIN_GRID_SUPPORT_BATTERY_CAPACITY_AH, MAX_GRID_SUPPORT_BATTERY_CAPACITY_AH);
    const gridSupportReserveAh = clampRounded(value.gridSupportReserveAh, MIN_GRID_SUPPORT_RESERVE_AH, MAX_GRID_SUPPORT_RESERVE_AH);
    const gridSupportStartHour = clampRounded(value.gridSupportStartHour, MIN_GRID_SUPPORT_HOUR, MAX_GRID_SUPPORT_HOUR);
    const gridSupportEndHour = clampRounded(value.gridSupportEndHour, MIN_GRID_SUPPORT_HOUR, MAX_GRID_SUPPORT_HOUR);
    const gridSupportMaxDischargeA = clampRounded(value.gridSupportMaxDischargeA, MIN_GRID_SUPPORT_MAX_DISCHARGE_A, MAX_GRID_SUPPORT_MAX_DISCHARGE_A);
    const gridSupportForecastConfidencePct = clampRounded(value.gridSupportForecastConfidencePct, MIN_GRID_SUPPORT_PCT, MAX_GRID_SUPPORT_PCT);
    const gridSupportSolarAssistGainPct = clampRounded(value.gridSupportSolarAssistGainPct, MIN_GRID_SUPPORT_PCT, MAX_GRID_SUPPORT_PCT);
    const gridSupportWeakForecastBlockAh = clampRounded(value.gridSupportWeakForecastBlockAh, MIN_GRID_SUPPORT_WEAK_FORECAST_AH, MAX_GRID_SUPPORT_WEAK_FORECAST_AH);
    const gridSupportMinGridImportW = clampRounded(value.gridSupportMinGridImportW, MIN_GRID_SUPPORT_MIN_GRID_IMPORT_W, MAX_GRID_SUPPORT_MIN_GRID_IMPORT_W);
    const gridSupportDisableNoSun = Boolean(value.gridSupportDisableNoSun);
    const gridSupportDisableNoSunBelowW = clampRounded(value.gridSupportDisableNoSunBelowW, MIN_GRID_SUPPORT_DISABLE_NO_SUN_BELOW_W, MAX_GRID_SUPPORT_DISABLE_NO_SUN_BELOW_W);
    const exportGuardEnabled = Boolean(value.exportGuardEnabled);
    const rawForceChargeGridW = Number(value.forceChargeGridW);
    const forceChargeEnabled = Boolean(value.forceChargeEnabled);
    const forceChargeLimiterEnabled = Boolean(value.forceChargeLimiterEnabled);
    const rawFcLimiterStart = Number(value.forceChargeLimiterStart);
    const rawFcLimiterRelease = Number(value.forceChargeLimiterRelease);
    const rawFcLimiterFull = Number(value.forceChargeLimiterFull);
    const gridSupportW = Math.round(rawGridSupportW);
    const forceChargeGridW = Math.round(rawForceChargeGridW);
    const inRange = [start, release, full].every(
        setting => Number.isFinite(setting) && setting >= MIN_SETTING && setting <= MAX_SETTING
    );
    const validGridSupportW = Number.isFinite(rawGridSupportW)
        && gridSupportW >= MIN_GRID_SUPPORT_W
        && gridSupportW <= MAX_GRID_SUPPORT_W;
    const validForceChargeGridW = Number.isFinite(rawForceChargeGridW)
        && forceChargeGridW >= MIN_FORCE_CHARGE_W
        && forceChargeGridW <= MAX_FORCE_CHARGE_W;
    const fcLimiterFinite = [rawFcLimiterStart, rawFcLimiterRelease, rawFcLimiterFull].every(Number.isFinite);
    const fcLimiterInRange = fcLimiterFinite && [rawFcLimiterStart, rawFcLimiterRelease, rawFcLimiterFull].every(
        v => v >= MIN_FC_LIMITER && v <= MAX_FC_LIMITER
    );

    if (!inRange || !validGridSupportW || !validForceChargeGridW || !(full > start) || !(start >= release)
        || !fcLimiterFinite || !fcLimiterInRange
        || !(rawFcLimiterRelease > rawFcLimiterStart) || !(rawFcLimiterStart > rawFcLimiterFull)) {
        return null;
    }

    return {
        enabled, start, release, full, gridSupportW, gridSupportMode,
        gridSupportBatteryCapacityAh, gridSupportReserveAh, gridSupportStartHour, gridSupportEndHour,
        gridSupportMaxDischargeA, gridSupportForecastConfidencePct, gridSupportSolarAssistGainPct,
        gridSupportWeakForecastBlockAh, gridSupportMinGridImportW,
        gridSupportDisableNoSun, gridSupportDisableNoSunBelowW,
        exportGuardEnabled,
        forceChargeEnabled, forceChargeGridW,
        forceChargeLimiterEnabled,
        forceChargeLimiterStart: rawFcLimiterStart,
        forceChargeLimiterRelease: rawFcLimiterRelease,
        forceChargeLimiterFull: rawFcLimiterFull
    };
}

const normalized = normalizeSettings(msg.payload);

if (!normalized) {
    return [
        null,
        { hvStatus: { level: 'error', message: 'Invalid values. HV: 50–60 V, full > start >= release. Grid support 0–1000 W. Adaptive support: capacity 0–2000 Ah, reserve 0–1000 Ah, hours 0–23, max discharge 0–50 A, confidence/gain 0–100 %, min grid import 200–1000 W, low-sun threshold 0–5000 W. Force charge 0–3000 W. FC limiter: 40–60 V, release > start > full.' } },
        null
    ];
}

const settings = {
    enabled: normalized.enabled,
    start: normalized.start,
    release: normalized.release,
    full: normalized.full,
    gridSupportW: normalized.gridSupportW,
    gridSupportMode: normalized.gridSupportMode,
    gridSupportBatteryCapacityAh: normalized.gridSupportBatteryCapacityAh,
    gridSupportReserveAh: normalized.gridSupportReserveAh,
    gridSupportStartHour: normalized.gridSupportStartHour,
    gridSupportEndHour: normalized.gridSupportEndHour,
    gridSupportMaxDischargeA: normalized.gridSupportMaxDischargeA,
    gridSupportForecastConfidencePct: normalized.gridSupportForecastConfidencePct,
    gridSupportSolarAssistGainPct: normalized.gridSupportSolarAssistGainPct,
    gridSupportWeakForecastBlockAh: normalized.gridSupportWeakForecastBlockAh,
    gridSupportMinGridImportW: normalized.gridSupportMinGridImportW,
    gridSupportDisableNoSun: normalized.gridSupportDisableNoSun,
    gridSupportDisableNoSunBelowW: normalized.gridSupportDisableNoSunBelowW,
    exportGuardEnabled: normalized.exportGuardEnabled,
    forceChargeEnabled: normalized.forceChargeEnabled,
    forceChargeGridW: normalized.forceChargeGridW,
    forceChargeLimiterEnabled: normalized.forceChargeLimiterEnabled,
    forceChargeLimiterStart: normalized.forceChargeLimiterStart,
    forceChargeLimiterRelease: normalized.forceChargeLimiterRelease,
    forceChargeLimiterFull: normalized.forceChargeLimiterFull,
    updatedAt: new Date().toISOString(),
    source: 'dashboard'
};

flow.set('highVoltageSettings', settings);

return [
    {
        filename: CONFIG_PATH,
        payload: JSON.stringify(settings, null, 2),
        encoding: 'utf8'
    },
    { hvStatus: { level: 'success', message: 'High-voltage settings saved.' } },
    { topic: 'high-voltage-settings-saved', payload: settings }
];

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `02 Build analytics tab model.js` and the embedded `func` for "Build analytics tab model"
//   in `flows.json` must always stay synchronized.
// Inputs (message topics):
// - `controller-trace`  -> stores trace payload into flow context `dashboardControllerTrace`
// - any other topic / inject -> rebuilds the full analytics model from stored flow context
// Flow context read:
// - `dailySummary`             -> completed hourly energy rows for today
// - `dashboardLiveHour`        -> live (partial) current-hour energy accumulators
// - `dashboardControllerTrace` -> latest controller trace for diagnostics panel
// - `solarForecastToday`       -> today's solar forecast summary (energyKWh)
// - `solarForecastAdjusted`    -> hourly adjusted solar forecast map (hour key -> W)
// Outputs (6):
// - output 1 -> KPI payload  (totalGridKWh, totalAcKWh, forecastSolarKWh, liveGridW, liveAcW, …)
// - output 2 -> actual chart  (hourly Grid Wh / AC Wh bar series)
// - output 3 -> forecast chart (adjusted hourly solar forecast W; null when no data)
// - output 4 -> diagnostics payload (active window, setpoint, charge current, voltages, …)
// - output 5 -> hourly rows payload (dateKey + rows array for table display)
// - output 6 -> pending payload (lists available vs. missing metrics)
// Change notes:
// 1. Initial version: builds KPI, actual/forecast charts, diagnostics, hourly rows, and pending panels.
//    Reads dailySummary + dashboardLiveHour for grid/AC Wh totals; reads solarForecastAdjusted for
//    per-hour solar forecast; reads dashboardControllerTrace for diagnostics.
// 2. Added actualSolarKWh to KPI: sums solarWh from completed dailySummary rows + live hour.
//    solarWh is hourly PV charger generation accumulated from `/Dc/Pv/Power`.
// 3. Added same-day load forecast series and KPI.
//    Forecast uses observed AC hourly usage from completed hours plus the live partial hour,
//    then projects future hours with time-of-day bucket averages.
// 4. Added surplus forecast/actual series.
//    Surplus is a non-negative proxy: max(0, solar - AC load), without routing breakdown.
// 5. Added PV routing totals.
//    Routing uses a no-export proxy that matches the controller's non-negative grid-import behavior:
//    PV->Load = min(PV, load), PV->Battery = max(0, PV - load), PV->Grid = 0.
// 6. Added capacity tariff card data (`kpiPayload.tariff`) from the controller trace `tariff` block:
//    active season/tier, today's grid import, energy left today at the season plan, today's billable
//    peak hour, the month's top-3-day average tier, and both season profiles (setpoints + grid current).
// ==========================

if (msg.topic === 'controller-trace' && msg.payload) {
    flow.set('dashboardControllerTrace', msg.payload);
}

function dayKeyFromDate(date) {
    return [
        date.getFullYear(),
        String(date.getMonth() + 1).padStart(2, '0'),
        String(date.getDate()).padStart(2, '0')
    ].join('-');
}

function hourLabelFromKey(hourKey) {
    return hourKey.substring(11, 13) + ':00';
}

function average(values) {
    return values.length > 0
        ? values.reduce((sum, value) => sum + value, 0) / values.length
        : 0;
}

function bucketKeyForHour(hour) {
    if (hour < 6 || hour >= 22) {
        return 'night';
    }
    if (hour < 12) {
        return 'morning';
    }
    if (hour < 17) {
        return 'day';
    }
    return 'evening';
}

function buildLoadForecast(todayKey, rows, liveState, now) {
    const buckets = {
        night: [],
        morning: [],
        day: [],
        evening: []
    };
    const observedHourlyWh = [];
    const forecastMap = {};
    const currentHour = now.getHours();
    const secondsIntoHour = (now.getMinutes() * 60) + now.getSeconds();
    const elapsedFraction = Math.min(1, Math.max(1 / 3600, secondsIntoHour / 3600));
    const remainingFraction = Math.max(0, 1 - elapsedFraction);
    let liveHourForecastW = null;

    rows.forEach(row => {
        const hour = Number(String(row.hour || '').substring(0, 2));
        const acWh = Math.max(0, Number(row.acWh) || 0);

        if (!Number.isInteger(hour)) {
            return;
        }

        observedHourlyWh.push(acWh);
        buckets[bucketKeyForHour(hour)].push(acWh);
    });

    if (liveState && liveState.hourKey && String(liveState.hourKey).startsWith(todayKey)) {
        const liveHour = Number(String(liveState.hourKey).substring(11, 13));
        const liveAcWh = Math.max(0, Number(liveState.acWh) || 0);
        const liveAcW = Math.max(0, Math.round(Number(liveState.acPowerW) || 0));
        const normalizedLiveHourWh = elapsedFraction > 0 ? liveAcWh / elapsedFraction : liveAcWh;

        if (Number.isInteger(liveHour)) {
            observedHourlyWh.push(normalizedLiveHourWh);
            buckets[bucketKeyForHour(liveHour)].push(normalizedLiveHourWh);
        }

        if (liveAcW > 0) {
            liveHourForecastW = liveAcW;
        }
    }

    const globalAverageWh = average(observedHourlyWh);
    const bucketAverages = {
        night: average(buckets.night) || globalAverageWh,
        morning: average(buckets.morning) || globalAverageWh,
        day: average(buckets.day) || globalAverageWh,
        evening: average(buckets.evening) || globalAverageWh
    };

    let remainingForecastWh = 0;

    for (let hour = 0; hour < 24; hour += 1) {
        const label = String(hour).padStart(2, '0') + ':00';
        const bucketAverageWh = bucketAverages[bucketKeyForHour(hour)] || 0;
        const forecastW = hour === currentHour && liveHourForecastW !== null
            ? liveHourForecastW
            : Math.max(0, Math.round(bucketAverageWh));

        forecastMap[label] = forecastW;

        if (hour > currentHour) {
            remainingForecastWh += forecastW;
        }
        else if (hour === currentHour) {
            remainingForecastWh += forecastW * remainingFraction;
        }
    }

    return {
        forecastMap,
        remainingForecastWh,
        hasObservedData: observedHourlyWh.length > 0
    };
}

const todayKey = dayKeyFromDate(new Date());
const summary = flow.get('dailySummary') || { dateKey: '', hours: [] };
const summaryHours = Array.isArray(summary.hours)
    ? summary.hours.slice().sort((a, b) => a.hour.localeCompare(b.hour))
    : [];
const live = flow.get('dashboardLiveHour') || null;
const trace = flow.get('dashboardControllerTrace') || null;
const solarToday = flow.get('solarForecastToday') || {};
const solarAdjusted = flow.get('solarForecastAdjusted') || {};

const totalGridCompleted = summaryHours.reduce((sum, row) => sum + (Number(row.gridWh) || 0), 0);
const totalAcCompleted = summaryHours.reduce((sum, row) => sum + (Number(row.acWh) || 0), 0);
const totalSolarCompleted = summaryHours.reduce((sum, row) => sum + (Number(row.solarWh) || 0), 0);
const liveGridWh = live && live.hourKey && live.hourKey.startsWith(todayKey) ? Math.round(Number(live.gridWh) || 0) : 0;
const liveAcWh = live && live.hourKey && live.hourKey.startsWith(todayKey) ? Math.round(Number(live.acWh) || 0) : 0;
const liveSolarWh = live && live.hourKey && live.hourKey.startsWith(todayKey) ? Math.round(Number(live.solarWh) || 0) : 0;
const totalGridToday = totalGridCompleted + liveGridWh;
const totalAcToday = totalAcCompleted + liveAcWh;
const totalSolarToday = totalSolarCompleted + liveSolarWh;
const loadForecast = buildLoadForecast(todayKey, summaryHours, live, new Date());
const forecastLoadTodayWh = totalAcToday + loadForecast.remainingForecastWh;
const actualSurplusTodayWh = summaryHours.reduce(
    (sum, row) => sum + Math.max(0, (Number(row.solarWh) || 0) - (Number(row.acWh) || 0)),
    0
) + Math.max(0, liveSolarWh - liveAcWh);
const actualPvToLoadTodayWh = summaryHours.reduce(
    (sum, row) => sum + Math.min(Math.max(0, Number(row.solarWh) || 0), Math.max(0, Number(row.acWh) || 0)),
    0
) + Math.min(liveSolarWh, liveAcWh);
const actualPvToBatteryTodayWh = actualSurplusTodayWh;
const actualPvToGridTodayWh = 0;

const hourlyRows = summaryHours.map(row => ({
    hour: row.hour,
    gridWh: Number(row.gridWh) || 0,
    acWh: Number(row.acWh) || 0,
    solarWh: Number(row.solarWh) || 0,
    surplusWh: Math.max(0, (Number(row.solarWh) || 0) - (Number(row.acWh) || 0)),
    forecastSolarW: null,
    forecastLoadW: null,
    forecastSurplusW: null,
    state: 'done'
}));

if (live && live.hourKey && live.hourKey.startsWith(todayKey)) {
    hourlyRows.push({
        hour: hourLabelFromKey(live.hourKey) + ' *',
        gridWh: liveGridWh,
        acWh: liveAcWh,
        solarWh: liveSolarWh,
        surplusWh: Math.max(0, liveSolarWh - liveAcWh),
        forecastSolarW: null,
        forecastLoadW: null,
        forecastSurplusW: null,
        state: 'live'
    });
}

const forecastHourlyMap = {};
const adjustedResult = solarAdjusted.adjustedResult && typeof solarAdjusted.adjustedResult === 'object'
    ? solarAdjusted.adjustedResult
    : {};

Object.keys(adjustedResult).forEach(key => {
    if (!String(key).startsWith(todayKey)) {
        return;
    }
    const label = hourLabelFromKey(String(key));
    forecastHourlyMap[label] = Math.round(Number(adjustedResult[key]) || 0);
});

hourlyRows.forEach(row => {
    const normalizedHour = row.hour.replace(' *', '');
    row.forecastSolarW = Object.prototype.hasOwnProperty.call(forecastHourlyMap, normalizedHour)
        ? forecastHourlyMap[normalizedHour]
        : null;
    row.forecastLoadW = Object.prototype.hasOwnProperty.call(loadForecast.forecastMap, normalizedHour)
        ? loadForecast.forecastMap[normalizedHour]
        : null;
    row.forecastSurplusW = row.forecastSolarW !== null && row.forecastLoadW !== null
        ? Math.max(0, row.forecastSolarW - row.forecastLoadW)
        : null;
});

const allForecastHours = Array.from({ length: 24 }, (_, hour) => String(hour).padStart(2, '0') + ':00');
const forecastSurplusTodayWh = allForecastHours.reduce((sum, hourLabel) => {
    const solarW = Object.prototype.hasOwnProperty.call(forecastHourlyMap, hourLabel)
        ? forecastHourlyMap[hourLabel]
        : 0;
    const loadW = loadForecast.forecastMap[hourLabel] || 0;

    return sum + Math.max(0, solarW - loadW);
}, 0);
const forecastPvToLoadTodayWh = allForecastHours.reduce((sum, hourLabel) => {
    const solarW = Object.prototype.hasOwnProperty.call(forecastHourlyMap, hourLabel)
        ? forecastHourlyMap[hourLabel]
        : 0;
    const loadW = loadForecast.forecastMap[hourLabel] || 0;

    return sum + Math.min(solarW, loadW);
}, 0);
const forecastPvToBatteryTodayWh = forecastSurplusTodayWh;
const forecastPvToGridTodayWh = 0;
const forecastChart = {
    labels: allForecastHours,
    series: ['Adjusted solar forecast W', 'Forecast load W', 'Forecast surplus W'],
    data: [
        allForecastHours.map(hour => Object.prototype.hasOwnProperty.call(forecastHourlyMap, hour) ? forecastHourlyMap[hour] : 0),
        allForecastHours.map(hour => loadForecast.forecastMap[hour] || 0),
        allForecastHours.map(hour => {
            const solarW = Object.prototype.hasOwnProperty.call(forecastHourlyMap, hour) ? forecastHourlyMap[hour] : 0;
            const loadW = loadForecast.forecastMap[hour] || 0;
            return Math.max(0, solarW - loadW);
        })
    ]
};

const actualChart = {
    labels: hourlyRows.map(row => row.hour),
    series: ['Grid Wh', 'AC Wh', 'Solar Wh', 'Surplus Wh'],
    data: [
        hourlyRows.map(row => row.gridWh),
        hourlyRows.map(row => row.acWh),
        hourlyRows.map(row => row.solarWh),
        hourlyRows.map(row => row.surplusWh)
    ]
};

const forecastSolarKWh = Number(solarToday.energyKWh) || 0;
const liveGridW = live ? Math.round(Number(live.gridPowerW) || 0) : 0;
const liveAcW = live ? Math.round(Number(live.acPowerW) || 0) : 0;
const liveSolarW = trace ? Math.round(Number(trace.solarGenerationW) || 0) : 0;
const livePvToLoadW = Math.min(liveSolarW, liveAcW);
const livePvToBatteryW = Math.max(0, liveSolarW - livePvToLoadW);
const livePvToGridW = 0;
const totalInputW = liveGridW + liveSolarW;
const efficiencyPct = totalInputW > 50
    ? Math.round(Math.min(100, liveAcW / totalInputW * 100) * 10) / 10
    : null;
const lossesW = totalInputW > 50 ? Math.max(0, totalInputW - liveAcW) : null;
function kwText(watts) {
    return (Math.max(0, Number(watts) || 0) / 1000).toFixed(2);
}

function formatProfile(profile) {
    if (!profile) {
        return '';
    }

    return `tier ${profile.tier} (≤${kwText(profile.tierLimitW).replace(/\.?0+$/, '')} kW) | day ${profile.daySetpointW} W / ${profile.dayCurrentA} A`
        + ` | night +${profile.nightBonusPct}% ${profile.nightSetpointW} W / ${profile.nightCurrentA} A (billed ${profile.nightBillableW} W)`;
}

function buildTariffView(tariff) {
    if (!tariff || !tariff.summer || !tariff.winter) {
        return null;
    }

    const headroomWh = Number(tariff.todayPeakHeadroomWh) || 0;
    const peakHour = String(tariff.todayPeakHourKey || '').substring(11, 13);

    return {
        season: tariff.season,
        isWinter: tariff.season === 'WINTER',
        tier: tariff.tier,
        tierLimitKW: kwText(tariff.tierLimitW).replace(/\.?0+$/, ''),
        gridCurrentLimitA: tariff.gridCurrentLimitA,
