function shellQuote(script) {
    return "'" + String(script).replace(/'/g, "'\\''") + "'";
}

function escapeRegex(text) {
    return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function formatBytes(bytes) {
    const value = Math.max(0, Number(bytes) || 0);
    if (value >= 1024 * 1024 * 1024) {
        return (value / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
    }
    if (value >= 1024 * 1024) {
        return (value / (1024 * 1024)).toFixed(1) + ' MB';
    }
    if (value >= 1024) {
        return (value / 1024).toFixed(1) + ' KB';
    }
    return value + ' B';
}

// Shell helpers shared by every script: list backups + disk, and create an archive.
function scriptPrelude() {
    const plainPaths = BACKUP_PATHS.filter(path => !EXPANDED_DIRS[path]).join(' ');
    // Expanded folders are added child by child so excluded children never reach tar.
    const expandLines = Object.keys(EXPANDED_DIRS).map(dirPath =>
        '  if [ -d "$R/' + dirPath + '" ]; then for f in "$R/' + dirPath + '"/* "$R/' + dirPath + '"/.[!.]*; do [ -e "$f" ] || continue; '
        + 'case "${f##*/}" in ' + EXPANDED_DIRS[dirPath].join('|') + ') continue;; esac; add "' + dirPath + '/${f##*/}"; done; fi'
    );

    return [
        // R is the filesystem root (empty on the device; a temp folder in tests).
        'R=""',
        'B="$R' + BACKUP_DIR + '"',
        'list_backups() {',
        '  echo "@@USER $(id -un 2>/dev/null)"',
        '  echo "@@DF $(df -Pk "$B" 2>/dev/null | tail -n 1)"',
        '  for f in "$B"/*.tar.gz; do [ -f "$f" ] || continue; printf "@@B\\t%s\\t%s\\t%s\\n" "$(wc -c < "$f")" "$(date -r "$f" "+%Y-%m-%d %H:%M" 2>/dev/null)" "${f##*/}"; done',
        '}',
        'fail() { echo "@@ERROR $*"; list_backups; exit 0; }',
        'create_backup() {',
        '  NAME="$1-$(date +%Y%m%d-%H%M%S).tar.gz"',
        '  mkdir -p "$B" "$R/' + MANIFEST_PATH.replace(/\/[^/]+$/, '') + '" || fail "Cannot create $B"',
        '  L=""',
        '  add() { if [ -e "$R/$1" ]; then if [ -r "$R/$1" ]; then L="$L $1"; else echo "@@SKIPPED $1 (not readable)"; fi; fi; }',
        '  for p in ' + plainPaths + '; do add "$p"; done',
        ...expandLines,
        '  { echo "type=grid-control-backup"; echo "format=1"; echo "created=$(date "+%Y-%m-%d %H:%M:%S %z")"; echo "host=$(hostname)"; echo "venus=$(head -n 1 /opt/victronenergy/version 2>/dev/null)"; echo "user=$(id -un 2>/dev/null)"; for p in $L; do echo "path=$p"; done; } > "$R/' + MANIFEST_PATH + '" || fail "Cannot write manifest"',
        '  case " $L " in *" data/home/nodered/grid-control-config "*) ;; *) L="$L ' + MANIFEST_PATH + '";; esac',
        // GNU tar (Venus OS): skip daemontools runtime folders (`supervise`, root-only) at any depth.
        // BusyBox tar has no --exclude, so the option is only passed to GNU tar.
        '  EX=""; tar --version 2>/dev/null | grep -q GNU && EX="--exclude=supervise --exclude=lost+found"',
        '  tar -czf "$B/$NAME.part" $EX -C "$R/" $L 2>"$B/.tar-errors"',
        '  if tar -tzf "$B/$NAME.part" >/dev/null 2>&1; then mv "$B/$NAME.part" "$B/$NAME"; else rm -f "$B/$NAME.part"; sed "s/^/@@LOG /" "$B/.tar-errors"; fail "Archive could not be created"; fi',
        '  sed "s/^/@@LOG /" "$B/.tar-errors"; rm -f "$B/.tar-errors"',
        '  for p in $L; do echo "@@INCLUDED $p"; done',
        '  CREATED="$NAME"',
        '}'
    ].join('\n');
}

function buildRefreshScript() {
    return scriptPrelude() + '\nlist_backups';
}

function buildCreateScript() {
    return scriptPrelude() + '\ncreate_backup grid-backup\necho "@@CREATED $CREATED"\nlist_backups';
}

// `name` is validated against NAME_PATTERN and the current list before this is called.
function buildDeleteScript(name) {
    return scriptPrelude() + '\n' + [
        '[ -f "$B/' + name + '" ] || fail "Backup not found: ' + name + '"',
        'rm -f "$B/' + name + '" && [ ! -e "$B/' + name + '" ] || fail "Cannot delete ' + name + '"',
        'echo "@@DELETED ' + name + '"',
        'list_backups'
    ].join('\n');
}

function buildRestoreScript(name, restoreVenusSettings, restartNodeRed, enableDrivers) {
    const allowed = BACKUP_PATHS.map(escapeRegex).join('|');
    // Parent folder entries (`data/`, `data/home/`, ...) appear when an archive is repacked by another tool.
    const parents = Array.from(new Set(BACKUP_PATHS.reduce((list, path) => {
        const parts = path.split('/');
        for (let index = 1; index < parts.length; index += 1) {
            list.push(parts.slice(0, index).join('/') + '/');
        }
        return list;
    }, []))).map(escapeRegex).join('|');

    return scriptPrelude() + '\n' + [
        'F="$B/' + name + '"',
        'ST="$B/.restore-staging"',
        '[ -f "$F" ] || fail "Backup not found: ' + name + '"',
        'tar -tzf "$F" > "$B/.restore-list" 2>/dev/null || fail "Not a valid .tar.gz archive"',
        'grep -q "^' + escapeRegex(MANIFEST_PATH) + '$" "$B/.restore-list" || fail "Not a grid-control backup (manifest missing)"',
        'BAD=$(grep -v -E "^(' + allowed + ')(/|$)" "$B/.restore-list" | grep -v -E "^(' + parents + ')$" | head -n 3 | tr "\\n" " ")',
        '[ -z "$BAD" ] || fail "Archive contains unexpected paths: $BAD"',
        'grep -q "\\.\\./" "$B/.restore-list" && fail "Archive contains .. paths"',
        'create_backup pre-restore',
        'echo "@@SAFETY $CREATED"',
        'rm -rf "$ST"; mkdir -p "$ST" || fail "Cannot create staging folder"',
        'tar -xzf "$F" -C "$ST" 2>/dev/null || { rm -rf "$ST"; fail "Extract failed"; }',
        'NR=0',
        'for p in ' + BACKUP_PATHS.join(' ') + '; do',
        '  [ -e "$ST/$p" ] || continue',
        '  if [ "$p" = "' + VENUS_SETTINGS_PATH + '" ] && [ "' + (restoreVenusSettings ? '1' : '0') + '" != "1" ]; then echo "@@SKIP $p (Venus OS settings not selected)"; continue; fi',
        '  D="$R/${p%/*}"',
        '  if mkdir -p "$D" && cp -a "$ST/$p" "$D/"; then echo "@@RESTORED $p"; [ "$p" = "' + NODE_RED_DIR + '" ] && NR=1; else echo "@@FAILED $p"; fi',
        'done',
        // Re-register every restored driver that ships an enable.sh (creates its services / rc.local hooks).
        'if [ "' + (enableDrivers ? '1' : '0') + '" = "1" ]; then',
        '  for e in "$ST/' + DRIVERS_DIR + '"/*/enable.sh; do',
        '    [ -f "$e" ] || continue',
        '    DRV="${e%/enable.sh}"; DRV="${DRV##*/}"',
        '    if [ -f "$R/' + DRIVERS_DIR + '/$DRV/enable.sh" ] && bash "$R/' + DRIVERS_DIR + '/$DRV/enable.sh" > "$B/.enable-$DRV.log" 2>&1; then echo "@@DRIVER $DRV"; else echo "@@FAILED ' + DRIVERS_DIR + '/$DRV/enable.sh"; fi',
        '    tail -n 5 "$B/.enable-$DRV.log" 2>/dev/null | sed "s/^/@@LOG [$DRV] /"; rm -f "$B/.enable-$DRV.log"',
        '  done',
        'fi',
        'rm -rf "$ST" "$B/.restore-list"',
        'if [ "$NR" = "1" ] && [ "' + (restartNodeRed ? '1' : '0') + '" = "1" ]; then ( sleep 5; for s in /service/node-red*; do svc -t "$s"; done ) >/dev/null 2>&1 & echo "@@RESTART Node-RED restarts in 5 s"; fi',
        'echo "@@DONE ' + name + '"',
        'list_backups'
    ].join('\n');
}

function parseScriptOutput(rawText) {
    const result = {
        user: '',
        disk: null,
        backups: [],
        created: '',
        safety: '',
        error: '',
        done: '',
        deleted: '',
        restart: '',
        drivers: [],
        included: [],
        restored: [],
        failed: [],
        skipped: [],
        log: []
    };

    String(rawText || '').split(/\r?\n/).forEach(line => {
        if (!line.trim()) {
            return;
        }
        if (line.startsWith('@@B\t')) {
            const parts = line.split('\t');
            const name = parts[3] || '';
            result.backups.push({
                name,
                size: Number(parts[1]) || 0,
                date: parts[2] || '',
                kind: name.startsWith('pre-restore-') ? 'safety' : (name.startsWith('uploaded-') ? 'uploaded' : 'backup')
            });
            return;
        }

        const match = line.match(/^@@([A-Z]+) ?(.*)$/);
        if (!match) {
            result.log.push(line);
            return;
        }

        const value = match[2].trim();
        switch (match[1]) {
            case 'USER': result.user = value; break;
            case 'DF': {
                const parts = value.split(/\s+/);
                if (parts.length >= 6 && Number(parts[1]) > 0) {
                    result.disk = {
                        totalText: formatBytes(Number(parts[1]) * 1024),
                        usedText: formatBytes(Number(parts[2]) * 1024),
                        availableText: formatBytes(Number(parts[3]) * 1024),
                        usePct: parseInt(parts[4], 10) || 0
                    };
                }
                break;
            }
            case 'CREATED': result.created = value; break;
            case 'SAFETY': result.safety = value; break;
            case 'ERROR': result.error = value; break;
            case 'DONE': result.done = value; break;
            case 'DELETED': result.deleted = value; break;
            case 'RESTART': result.restart = value; break;
            case 'DRIVER': result.drivers.push(value); break;
            case 'INCLUDED': result.included.push(value); break;
            case 'RESTORED': result.restored.push(value); break;
            case 'FAILED': result.failed.push(value); break;
            case 'SKIP':
            case 'SKIPPED': result.skipped.push(value); break;
            case 'LOG': result.log.push(value); break;
            default: result.log.push(line);
        }
    });

    result.backups.sort((a, b) => (b.date + b.name).localeCompare(a.date + a.name));
    return result;
}

function getState() {
    return flow.get(STATE_KEY) || {
        backups: [],
        disk: null,
        user: '',
        busy: '',
        busySince: 0,
        result: null,
        updatedAt: ''
    };
}

function emit(state, execPayload, action) {
    state.updatedAt = new Date().toISOString();
    flow.set(STATE_KEY, state);

    const view = Object.assign({}, state, {
        backups: state.backups.map(backup => Object.assign({}, backup, { sizeText: formatBytes(backup.size) })),
        contents: BACKUP_PATHS.map(path => ({ path: '/' + path, label: BACKUP_LABELS[path] || path }))
    });

    return [
        { topic: 'backup-state', payload: view },
        execPayload ? { topic: 'backup-exec', backupAction: action, payload: shellQuote(execPayload) } : null
    ];
}

let state = getState();
const nowTs = Date.now();

if (state.busy && nowTs - (Number(state.busySince) || 0) > BUSY_TIMEOUT_MS) {
    state.busy = '';
}

if (msg.topic === 'backup-exec') {
    const parsed = parseScriptOutput(msg.payload);
    const action = msg.backupAction || 'refresh';

    state.backups = parsed.backups;
    state.disk = parsed.disk || state.disk;
    state.user = parsed.user || state.user;
    state.busy = '';

    if (action !== 'refresh' || parsed.error) {
        let message;
        if (parsed.error) {
            message = ({ restore: 'Restore failed: ', create: 'Backup failed: ', delete: 'Delete failed: ' }[action] || 'Error: ') + parsed.error;
        }
        else if (action === 'create') {
            message = 'Backup created: ' + parsed.created + ' (' + parsed.included.length + ' item(s)). Download it and keep it off the device.';
        }
        else if (action === 'delete') {
            message = 'Deleted ' + parsed.deleted + '.';
        }
        else {
            message = 'Restored ' + parsed.restored.length + ' item(s) from ' + parsed.done
                + (parsed.failed.length ? ', FAILED: ' + parsed.failed.length : '')
                + '. Safety backup: ' + parsed.safety + '.'
                + (parsed.restart ? ' ' + parsed.restart + '.' : '')
                + (parsed.drivers.length ? ' Drivers enabled: ' + parsed.drivers.join(', ') + ' - reboot the GX device to start them.' : '')
                + (parsed.restored.indexOf(VENUS_SETTINGS_PATH) >= 0 ? ' Reboot the GX device to apply Venus OS settings.' : '');
        }

        state.result = {
            ok: !parsed.error && parsed.failed.length === 0,
            action,
            message,
            at: new Date().toISOString(),
            included: parsed.included,
            restored: parsed.restored,
            failed: parsed.failed,
            skipped: parsed.skipped,
            log: parsed.log.slice(0, 40)
        };
    }

    return emit(state, null, action);
}

if (msg.topic === 'backup-uploaded') {
    const name = msg.payload && msg.payload.name ? String(msg.payload.name) : '';
    state.result = {
        ok: true,
        action: 'upload',
        message: 'Uploaded ' + name + '. Select it below to restore.',
        at: new Date().toISOString(),
        included: [], restored: [], failed: [], skipped: [], log: []
    };
    return emit(state, buildRefreshScript(), 'refresh');
}

if (msg.topic === 'backup-command' && msg.payload && typeof msg.payload === 'object') {
    const action = String(msg.payload.action || 'refresh');

    if (action === 'refresh') {
        return emit(state, buildRefreshScript(), 'refresh');
    }

    if (state.busy) {
        state.result = { ok: false, action, message: 'Busy: ' + state.busy + ' is still running.', at: new Date().toISOString(), included: [], restored: [], failed: [], skipped: [], log: [] };
        return emit(state, null, action);
    }

    if (action === 'create') {
        state.busy = 'backup';
        state.busySince = nowTs;
        state.result = { ok: true, action, message: 'Creating backup...', at: new Date().toISOString(), included: [], restored: [], failed: [], skipped: [], log: [] };
        return emit(state, buildCreateScript(), 'create');
    }

    if (action === 'delete') {
        const name = String(msg.payload.name || '');

        if (!NAME_PATTERN.test(name) || !state.backups.some(backup => backup.name === name)) {
            state.result = { ok: false, action, message: 'Backup not in the list: ' + name, at: new Date().toISOString(), included: [], restored: [], failed: [], skipped: [], log: [] };
            return emit(state, null, action);
        }

        state.busy = 'delete';
        state.busySince = nowTs;
        state.result = { ok: true, action, message: 'Deleting ' + name + '...', at: new Date().toISOString(), included: [], restored: [], failed: [], skipped: [], log: [] };
        return emit(state, buildDeleteScript(name), 'delete');
    }

    if (action === 'restore') {
        const name = String(msg.payload.name || '');
        const reject = message => {
            state.result = { ok: false, action, message, at: new Date().toISOString(), included: [], restored: [], failed: [], skipped: [], log: [] };
            return emit(state, null, action);
        };

        if (!NAME_PATTERN.test(name) || !state.backups.some(backup => backup.name === name)) {
            return reject('Select a backup from the list first.');
        }
        if (String(msg.payload.confirm || '').trim() !== 'RESTORE') {
            return reject('Type RESTORE in the confirmation field to start the restore.');
        }

        state.busy = 'restore';
        state.busySince = nowTs;
        state.result = { ok: true, action, message: 'Restoring ' + name + ' (safety backup first)...', at: new Date().toISOString(), included: [], restored: [], failed: [], skipped: [], log: [] };
        return emit(state, buildRestoreScript(
            name,
            Boolean(msg.payload.restoreVenusSettings),
            msg.payload.restartNodeRed !== false,
            msg.payload.enableDrivers !== false
        ), 'restore');
    }
}

// Dashboard connect or any other trigger: refresh the list.
return emit(state, buildRefreshScript(), 'refresh');

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `27 Serve backup download.js` and the embedded `func` for "Serve backup download"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - HTTP GET /grid-backup/download?name=<backup>.tar.gz -> streams the backup file to the browser.
// - Also answers HTTP errors caught from the backup file nodes (msg.error from the catch node).
// Input:
// - msg.req.query.name (from "GET /grid-backup/download")
// - msg.error + msg.res (from "Catch backup HTTP errors")
// Outputs (2):
// - output 1 -> file in "Read backup file" (msg.filename set, download headers set) -> http response
// - output 2 -> http response (validation error / caught error)
// Change notes:
// 1. Initial version.
// 2. Node status shows every request / error, to see whether a download reaches Node-RED
//    (e.g. through the VRM proxy).
// ==========================

const BACKUP_DIR = '/data/home/nodered/grid-control-backups';
const NAME_PATTERN = /^[A-Za-z0-9._-]+\.tar\.gz$/;

function timeLabel() {
    const now = new Date();
    return String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0') + ':' + String(now.getSeconds()).padStart(2, '0');
}

function textResponse(statusCode, text) {
    node.status({ fill: 'red', shape: 'dot', text: timeLabel() + ' ' + statusCode + ' ' + text });
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
    msg.payload = text;
    return [null, msg];
}

if (!msg.res) {
    return null;
}

if (msg.error) {
    return textResponse(500, 'Backup request failed: ' + (msg.error.message || 'unknown error'));
}

const name = String((msg.req && msg.req.query && msg.req.query.name) || '');

if (!NAME_PATTERN.test(name)) {
    return textResponse(400, 'Invalid backup name');
}

node.status({ fill: 'blue', shape: 'dot', text: timeLabel() + ' sending ' + name });
msg.filename = BACKUP_DIR + '/' + name;
msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'application/gzip',
    'Content-Disposition': 'attachment; filename="' + name + '"',
    'Cache-Control': 'no-store'
};
return [msg, null];

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `28 Store uploaded backup.js` and the embedded `func` for "Store uploaded backup"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - HTTP POST /grid-backup/upload (multipart, field `backup`) stores an uploaded backup in the
//   backup folder as `uploaded-<timestamp>-<name>.tar.gz`. Restoring is a separate, confirmed step.
// Flow:
// - stage 1 (from "POST /grid-backup/upload"): validate, set msg.filename -> output 1 (file write)
// - stage 2 (back from the file write node, msg.backupUploadName set): answer the browser on
//   output 2 and tell "Manage backup dashboard" on output 3
// Outputs (3):
// - output 1 -> file "Write uploaded backup"
// - output 2 -> http response
// - output 3 -> "Manage backup dashboard" (topic backup-uploaded)
// Change notes:
// 1. Initial version.
// ==========================

const BACKUP_DIR = '/data/home/nodered/grid-control-backups';
const MAX_UPLOAD_BYTES = 500 * 1024 * 1024;

function jsonResponse(statusCode, body) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = body;
    return msg;
}

if (msg.backupUploadName) {
    const name = msg.backupUploadName;
    jsonResponse(200, { ok: true, name });
    return [null, msg, { topic: 'backup-uploaded', payload: { name } }];
}

const files = msg.req && Array.isArray(msg.req.files) ? msg.req.files : [];
const file = files.find(item => item && item.fieldname === 'backup') || files[0];

if (!file || !file.buffer || !file.buffer.length) {
    return [null, jsonResponse(400, { ok: false, error: 'No file received' }), null];
}

if (file.buffer.length > MAX_UPLOAD_BYTES) {
    return [null, jsonResponse(413, { ok: false, error: 'File is larger than 500 MB' }), null];
}

// gzip magic bytes
if (file.buffer[0] !== 0x1f || file.buffer[1] !== 0x8b) {
    return [null, jsonResponse(400, { ok: false, error: 'Not a .tar.gz file' }), null];
}

const now = new Date();
const stamp = now.getFullYear()
    + String(now.getMonth() + 1).padStart(2, '0')
    + String(now.getDate()).padStart(2, '0') + '-'
    + String(now.getHours()).padStart(2, '0')
    + String(now.getMinutes()).padStart(2, '0')
    + String(now.getSeconds()).padStart(2, '0');
const baseName = String(file.originalname || 'backup.tar.gz')
    .replace(/\.tar\.gz$/i, '')
    .replace(/[^A-Za-z0-9._-]/g, '_')
    .substring(0, 80);
const name = 'uploaded-' + stamp + '-' + (baseName || 'backup') + '.tar.gz';

msg.filename = BACKUP_DIR + '/' + name;
msg.payload = file.buffer;
msg.backupUploadName = name;
return [msg, null, null];

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `29 Build device status.js` and the embedded `func` for "Build device status"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Device status page: CPU, load, memory, disks, temperature, uptime, Venus OS version, network
//   interfaces and traffic, TCP connections / listening ports, top processes and key Venus services.
// - Everything is read-only from /proc, /sys and standard tools, so it works as the `nodered` user.
// Inputs:
// - topic `device-status-command` (dashboard): payload { action: 'refresh' }
// - topic `device-status-exec` (exec stdout): script output with `@@` markers
// - anything else -> refresh
// Outputs (2):
// - output 1 -> dashboard template (topic `device-status`)
// - output 2 -> exec "Read device status" (`sh -c <payload>`)
// Sampling:
// - /proc/stat, /proc/net/dev and every /proc/<pid>/stat are read twice, 1 s apart; CPU % and
//   network rates are the difference. Process CPU % is the share of the whole machine.
// Change notes:
// 1. Initial version.
// 2. Process command lines and owners are read from /proc/<pid>/cmdline and /proc/<pid>/status
//    (+ /etc/passwd) instead of `ps`: BusyBox ps on Venus has no -e / truncates args, so services
//    started as Python scripts (comm cut to 15 chars, e.g. "dbus-serialbatt") were not recognised.
// 3. Adds the "BMS watchdog" state (flow `bmsWatchdogState`) to the view as `bmsWatchdog`.
// ==========================

const STATE_KEY = 'deviceStatusState';
const BUSY_TIMEOUT_MS = 30000;
const PAGE_KB = 4;
const KNOWN_PORTS = {
    22: 'SSH', 53: 'DNS', 80: 'HTTP (GUI)', 443: 'HTTPS (GUI)', 502: 'Modbus TCP', 1880: 'Node-RED',
    1881: 'Node-RED (HTTPS)', 1883: 'MQTT', 8883: 'MQTT TLS', 9001: 'MQTT websocket', 9443: 'MQTT websocket TLS',
    8088: 'GUI websocket', 3000: 'Signal K', 8000: 'Venus web', 5353: 'mDNS'
};
// Labels for the remote side of outgoing connections.
const REMOTE_PORTS = {
    53: 'DNS', 80: 'HTTP', 123: 'NTP', 443: 'HTTPS (VRM / cloud)', 1883: 'MQTT', 8883: 'MQTT TLS (VRM)', 22: 'SSH'
};
const TCP_STATES = {
    '01': 'ESTABLISHED', '02': 'SYN_SENT', '03': 'SYN_RECV', '04': 'FIN_WAIT1', '05': 'FIN_WAIT2',
    '06': 'TIME_WAIT', '07': 'CLOSE', '08': 'CLOSE_WAIT', '09': 'LAST_ACK', '0A': 'LISTEN', '0B': 'CLOSING'
};
// Key services, recognised by their command line.
const KEY_SERVICES = [
    { name: 'Node-RED', pattern: /node-red/ },
    { name: 'dbus-serialbattery', pattern: /dbus-serialbattery/ },
    { name: 'dbus-aggregate-batteries', pattern: /aggregate-batteries|aggregatebatteries/ },
    { name: 'VE.Bus (mk2-dbus)', pattern: /mk2-dbus/ },
    { name: 'System calc', pattern: /systemcalc/ },
    { name: 'Venus platform', pattern: /venus-platform/ },
    { name: 'Local settings', pattern: /localsettings/ },
    { name: 'GUI', pattern: /gui-v2|venus-gui|\/gui\b|\bgui\s/ },
    { name: 'MQTT broker', pattern: /flashmq|mosquitto/ },
    { name: 'VRM logger', pattern: /vrmlogger/ },
    { name: 'Modbus TCP', pattern: /modbustcp/ },
    { name: 'D-Bus daemon', pattern: /dbus-daemon/ },
    { name: 'SSH server', pattern: /dropbear|sshd/ },
    { name: 'Web server', pattern: /nginx|hiawatha|lighttpd/ }
];

const SCRIPT = [
    'echo "@@HOST $(hostname 2>/dev/null)"',
    'echo "@@USER $(id -un 2>/dev/null)"',
    'echo "@@KERNEL $(uname -r 2>/dev/null)"',
    'echo "@@MODEL $(tr -d "\\000" 2>/dev/null < /proc/device-tree/model)"',
    'echo "@@VENUS $(head -n 2 /opt/victronenergy/version 2>/dev/null | tr "\\n" " ")"',
    'echo "@@DATE $(date "+%Y-%m-%d %H:%M:%S %Z")"',
    'echo "@@UPTIME $(cat /proc/uptime)"',
    'echo "@@LOAD $(cat /proc/loadavg)"',
    'echo "@@NCPU $(grep -c "^processor" /proc/cpuinfo)"',
    'echo "@@CPUMODEL $(grep -m 1 -i -E "^(model name|hardware|cpu model)" /proc/cpuinfo | cut -d: -f2-)"',
    'for t in /sys/class/thermal/thermal_zone*/temp; do [ -r "$t" ] && echo "@@TEMP ${t%/temp} $(cat "$t")"; done',
    'grep -E "^(MemTotal|MemFree|MemAvailable|Buffers|Cached|SwapTotal|SwapFree):" /proc/meminfo | sed "s/^/@@MEM /"',
    'df -Pk 2>/dev/null | sed "1d; s/^/@@DF /"',
    'ip -o -4 addr show 2>/dev/null | sed "s/^/@@IP /"',
    'sample() {',
    '  echo "@@SAMPLE $1"',
    '  head -n 1 /proc/stat | sed "s/^/@@CPU /"',
    '  sed "1,2d; s/^/@@NET /" /proc/net/dev 2>/dev/null',
    '  for d in /proc/[0-9]*; do read -r st 2>/dev/null < "$d/stat" && echo "@@P $st"; done',
    '}',
    'sample 1',
    'sleep 1',
    'sample 2',
    // Full command line + owner straight from /proc: `comm` is cut to 15 chars (e.g. "dbus-serialbatt")
    // and BusyBox `ps` has no -e and truncates args, so it cannot be relied on.
    'cut -d: -f1,3 /etc/passwd 2>/dev/null | sed "s/^/@@PASSWD /"',
    'for d in /proc/[0-9]*; do',
    '  u=""; while read -r k v rest; do [ "$k" = "Uid:" ] && { u=$v; break; }; done 2>/dev/null < "$d/status"',
    '  printf "@@ARGS %s %s " "${d#/proc/}" "${u:--}"; tr "\\000" " " 2>/dev/null < "$d/cmdline"; echo',
    'done',
    'sed "1d; s/^/@@TCP /" /proc/net/tcp 2>/dev/null',
    'sed "1d; s/^/@@TCP6 /" /proc/net/tcp6 2>/dev/null',
    'true'
].join('\n');

function shellQuote(script) {
    return "'" + String(script).replace(/'/g, "'\\''") + "'";
}

function formatBytes(bytes) {
    const value = Math.max(0, Number(bytes) || 0);
    if (value >= 1024 * 1024 * 1024) {
        return (value / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
    }
    if (value >= 1024 * 1024) {
        return (value / (1024 * 1024)).toFixed(1) + ' MB';
    }
    if (value >= 1024) {
        return (value / 1024).toFixed(1) + ' KB';
    }
    return Math.round(value) + ' B';
}

function formatDuration(seconds) {
    const total = Math.max(0, Math.floor(Number(seconds) || 0));
    const days = Math.floor(total / 86400);
    const hours = Math.floor((total % 86400) / 3600);
    const minutes = Math.floor((total % 3600) / 60);
    return (days ? days + 'd ' : '') + hours + 'h ' + minutes + 'm';
}

function parseProcStat(line) {
    const open = line.indexOf('(');
    const close = line.lastIndexOf(')');
    if (open < 0 || close < 0) {
        return null;
    }
    const rest = line.substring(close + 2).split(' ');
    // field n of /proc/<pid>/stat is rest[n - 3]
    return {
        pid: Number(line.substring(0, open).trim()),
        comm: line.substring(open + 1, close),
        state: rest[0],
        ticks: (Number(rest[11]) || 0) + (Number(rest[12]) || 0),
        threads: Number(rest[17]) || 1,
        rssKb: (Number(rest[21]) || 0) * PAGE_KB
    };
}

function parseCpuLine(line) {
    const values = line.trim().split(/\s+/).slice(1).map(Number);
    const idle = (values[3] || 0) + (values[4] || 0);
    const total = values.slice(0, 8).reduce((sum, value) => sum + (value || 0), 0);
    return { idle, total };
}

function hexToIpv4(hex) {
    const parts = [];
    for (let index = 6; index >= 0; index -= 2) {
        parts.push(parseInt(hex.substring(index, index + 2), 16));
    }
    return parts.join('.');
}

function hexToIp(hex) {
    if (hex.length === 8) {
        return hexToIpv4(hex);
    }
    // IPv6: four little-endian 32-bit words
    const words = [0, 1, 2, 3].map(index => hex.substring(index * 8, index * 8 + 8));
    const bytes = [];
    words.forEach(word => {
        for (let index = 6; index >= 0; index -= 2) {
            bytes.push(word.substring(index, index + 2));
        }
    });
    const joined = bytes.join('').toLowerCase();
    if (joined.startsWith('00000000000000000000ffff')) {
        return hexToIpv4(words[3]);
    }
    if (/^0+$/.test(joined)) {
        return '::';
    }
    if (joined === '00000000000000000000000000000001') {
        return '::1';
    }
    const groups = [];
    for (let index = 0; index < 32; index += 4) {
        groups.push(joined.substring(index, index + 4).replace(/^0{1,3}/, ''));
    }
    return groups.join(':');
}

function parseTcpLine(line, family) {
    const parts = line.trim().split(/\s+/);
    if (parts.length < 4 || parts[1].indexOf(':') < 0) {
        return null;
    }
    const [localHex, localPortHex] = parts[1].split(':');
    const [remoteHex, remotePortHex] = parts[2].split(':');
    return {
        family,
        localIp: hexToIp(localHex),
        localPort: parseInt(localPortHex, 16),
        remoteIp: hexToIp(remoteHex),
        remotePort: parseInt(remotePortHex, 16),
        state: TCP_STATES[parts[3].toUpperCase()] || parts[3]
    };
}

function portLabel(port) {
    return KNOWN_PORTS[port] || '';
}

function parseOutput(rawText) {
    const info = { temps: [], mem: {}, disks: [], ips: [], tcp: [], ps: {}, users: {} };
    const samples = { 1: { cpu: null, net: {}, procs: {} }, 2: { cpu: null, net: {}, procs: {} } };
    let sample = 1;

    String(rawText || '').split(/\r?\n/).forEach(line => {
        const match = line.match(/^@@([A-Z0-9]+) ?(.*)$/);
        if (!match) {
            return;
        }
        const value = match[2];
        const current = samples[sample];

        switch (match[1]) {
            case 'HOST': info.host = value.trim(); break;
            case 'USER': info.user = value.trim(); break;
            case 'KERNEL': info.kernel = value.trim(); break;
            case 'MODEL': info.model = value.trim(); break;
            case 'VENUS': info.venus = value.trim(); break;
            case 'DATE': info.date = value.trim(); break;
            case 'UPTIME': info.uptimeSec = Number(value.trim().split(/\s+/)[0]) || 0; break;
            case 'LOAD': {
                const parts = value.trim().split(/\s+/);
                info.load = [Number(parts[0]) || 0, Number(parts[1]) || 0, Number(parts[2]) || 0];
                info.runnable = parts[3] || '';
                break;
            }
            case 'NCPU': info.ncpu = Math.max(1, Number(value) || 1); break;
            case 'CPUMODEL': info.cpuModel = value.trim(); break;
            case 'TEMP': {
                const parts = value.trim().split(/\s+/);
                const milli = Number(parts[1]);
                if (Number.isFinite(milli)) {
                    info.temps.push({ zone: (parts[0] || '').split('/').pop(), celsius: Math.round(milli / 100) / 10 });
                }
                break;
            }
            case 'MEM': {
                const parts = value.trim().match(/^(\w+):\s+(\d+)/);
                if (parts) {
                    info.mem[parts[1]] = Number(parts[2]) || 0;
                }
                break;
            }
            case 'DF': {
                const parts = value.trim().split(/\s+/);
                if (parts.length >= 6 && Number(parts[1]) > 0) {
                    info.disks.push({
                        fs: parts[0],
                        mount: parts.slice(5).join(' '),
                        totalKb: Number(parts[1]) || 0,
                        usedKb: Number(parts[2]) || 0,
                        availableKb: Number(parts[3]) || 0,
                        usePct: parseInt(parts[4], 10) || 0
                    });
                }
                break;
            }
            case 'IP': {
                const parts = value.trim().match(/^\d+:\s+(\S+)\s+inet\s+(\S+)/);
                if (parts) {
                    info.ips.push({ iface: parts[1], cidr: parts[2] });
                }
                break;
            }
            case 'SAMPLE': sample = Number(value) === 2 ? 2 : 1; break;
            case 'CPU': samples[sample].cpu = parseCpuLine(value); break;
            case 'NET': {
                const parts = value.split(':');
                if (parts.length >= 2) {
                    const fields = parts[1].trim().split(/\s+/).map(Number);
                    current.net[parts[0].trim()] = { rx: fields[0] || 0, tx: fields[8] || 0 };
                }
                break;
            }
            case 'P': {
                const proc = parseProcStat(value);
                if (proc) {
                    current.procs[proc.pid] = proc;
                }
                break;
            }
            case 'PASSWD': {
                const parts = value.trim().split(':');
                if (parts.length >= 2) {
                    info.users[parts[1]] = parts[0];
                }
                break;
            }
            case 'ARGS': {
                const parts = value.match(/^(\d+) (\S+) ?(.*)$/);
                if (parts) {
                    info.ps[Number(parts[1])] = { uid: parts[2], args: parts[3].trim() };
                }
                break;
            }
            case 'TCP':
            case 'TCP6': {
                const entry = parseTcpLine(value, match[1] === 'TCP6' ? 'IPv6' : 'IPv4');
                if (entry) {
                    info.tcp.push(entry);
                }
                break;
            }
            default:
                break;
        }
    });

    return { info, samples };
}

function buildView(parsed) {
    const { info, samples } = parsed;
    const ncpu = info.ncpu || 1;
    const cpu1 = samples[1].cpu;
    const cpu2 = samples[2].cpu;
    const deltaTotal = cpu1 && cpu2 ? Math.max(1, cpu2.total - cpu1.total) : 1;
    const cpuUsagePct = cpu1 && cpu2 ? Math.round((1 - (cpu2.idle - cpu1.idle) / deltaTotal) * 1000) / 10 : null;
    const elapsedSec = deltaTotal / ncpu / 100; // USER_HZ = 100

    // Processes
    const processes = Object.keys(samples[2].procs).map(pidKey => {
        const proc = samples[2].procs[pidKey];
        const before = samples[1].procs[pidKey];
        const psInfo = info.ps[proc.pid] || {};
        return {
            pid: proc.pid,
            name: proc.comm,
            user: psInfo.uid === undefined || psInfo.uid === '-' ? '' : (info.users[psInfo.uid] || psInfo.uid),
            // kernel threads have an empty cmdline
            args: String(psInfo.args || '[' + proc.comm + ']').substring(0, 160),
            cpuPct: before ? Math.round((proc.ticks - before.ticks) / deltaTotal * 1000) / 10 : 0,
            rssKb: proc.rssKb,
            rssText: formatBytes(proc.rssKb * 1024),
            threads: proc.threads,
            state: proc.state
        };
    });
    const threadCount = processes.reduce((sum, proc) => sum + proc.threads, 0);
    const topCpu = processes.slice().sort((a, b) => b.cpuPct - a.cpuPct || b.rssKb - a.rssKb).slice(0, 12);
    const topMem = processes.slice().sort((a, b) => b.rssKb - a.rssKb).slice(0, 12);

    // Key services
    const services = KEY_SERVICES.map(service => {
        const matches = processes.filter(proc => service.pattern.test(proc.args) || service.pattern.test(proc.name));
        return {
            name: service.name,
            running: matches.length > 0,
            pids: matches.map(proc => proc.pid).join(', '),
            cpuPct: Math.round(matches.reduce((sum, proc) => sum + proc.cpuPct, 0) * 10) / 10,
            rssText: formatBytes(matches.reduce((sum, proc) => sum + proc.rssKb, 0) * 1024)
        };
    });

    // Memory
    const mem = info.mem;
    const memTotalKb = mem.MemTotal || 0;
    const memAvailableKb = mem.MemAvailable !== undefined ? mem.MemAvailable : (mem.MemFree || 0) + (mem.Buffers || 0) + (mem.Cached || 0);
    const memUsedKb = Math.max(0, memTotalKb - memAvailableKb);
    const memUsedPct = memTotalKb ? Math.round(memUsedKb / memTotalKb * 1000) / 10 : 0;
    const swapTotalKb = mem.SwapTotal || 0;
    const swapUsedKb = Math.max(0, swapTotalKb - (mem.SwapFree || 0));

    // Disks: real filesystems first, tmpfs after
    const disks = info.disks.map(disk => Object.assign({}, disk, {
        totalText: formatBytes(disk.totalKb * 1024),
        usedText: formatBytes(disk.usedKb * 1024),
        availableText: formatBytes(disk.availableKb * 1024),
        isTmp: /tmpfs|devtmpfs|none|overlay/.test(disk.fs),
        level: disk.usePct >= 90 ? 'critical' : (disk.usePct >= 75 ? 'warning' : 'ok')
    })).sort((a, b) => Number(a.isTmp) - Number(b.isTmp) || a.mount.localeCompare(b.mount));

    // Network
    const interfaces = Object.keys(samples[2].net)
        .filter(name => name !== 'lo')
        .map(name => {
            const now = samples[2].net[name];
            const before = samples[1].net[name] || now;
            const ips = info.ips.filter(ip => ip.iface === name).map(ip => ip.cidr).join(', ');
            return {
                name,
                ips,
                rxRate: formatBytes(Math.max(0, now.rx - before.rx) / Math.max(0.5, elapsedSec)) + '/s',
                txRate: formatBytes(Math.max(0, now.tx - before.tx) / Math.max(0.5, elapsedSec)) + '/s',
                rxTotal: formatBytes(now.rx),
                txTotal: formatBytes(now.tx)
            };
        })
        .filter(iface => iface.ips || iface.rxTotal !== '0 B');

    // TCP
    const stateCounts = {};
    info.tcp.forEach(entry => { stateCounts[entry.state] = (stateCounts[entry.state] || 0) + 1; });
    const listenMap = {};
    info.tcp.filter(entry => entry.state === 'LISTEN').forEach(entry => {
        const key = entry.localPort;
        if (!listenMap[key]) {
            listenMap[key] = { port: entry.localPort, label: portLabel(entry.localPort), addresses: [] };
        }
        const address = entry.localIp + ' (' + entry.family + ')';
        if (listenMap[key].addresses.indexOf(address) < 0) {
            listenMap[key].addresses.push(address);
        }
    });
    const listening = Object.keys(listenMap).map(key => listenMap[key]).sort((a, b) => a.port - b.port);
    const listenPorts = new Set(listening.map(entry => entry.port));
    const established = info.tcp
        .filter(entry => entry.state === 'ESTABLISHED')
        .map(entry => {
            const inbound = listenPorts.has(entry.localPort);
            return {
                direction: inbound ? 'in' : 'out',
                local: entry.localIp + ':' + entry.localPort,
                remote: entry.remoteIp + ':' + entry.remotePort,
                service: inbound ? portLabel(entry.localPort) : (REMOTE_PORTS[entry.remotePort] || ''),
                loopback: /^127\.|^::1$/.test(entry.remoteIp)
            };
        });
    // Loopback connections (local services talking to each other) are only counted.
    const loopbackCount = established.filter(entry => entry.loopback).length;
    const external = established
        .filter(entry => !entry.loopback)
        .sort((a, b) => a.direction.localeCompare(b.direction) || a.remote.localeCompare(b.remote));

    // Health warnings
    const warnings = [];
    if (cpuUsagePct !== null && cpuUsagePct >= 85) {
        warnings.push('CPU usage ' + cpuUsagePct + '%');
    }
    if (info.load && info.load[1] > ncpu * 1.5) {
        warnings.push('Load (5 min) ' + info.load[1] + ' on ' + ncpu + ' CPU');
    }
    if (memTotalKb && memAvailableKb / memTotalKb < 0.15) {
        warnings.push('Low memory: ' + formatBytes(memAvailableKb * 1024) + ' available');
    }
    disks.filter(disk => !disk.isTmp && disk.usePct >= 85).forEach(disk => warnings.push('Disk ' + disk.mount + ' ' + disk.usePct + '% full'));
    info.temps.filter(temp => temp.celsius >= 75).forEach(temp => warnings.push('Temperature ' + temp.celsius + ' °C'));
    services.filter(service => !service.running && /Node-RED|dbus-serialbattery|VE.Bus|System calc/.test(service.name))
        .forEach(service => warnings.push(service.name + ' is not running'));

    return {
        updatedAt: new Date().toISOString(),
        sampledAt: info.date || '',
        host: info.host || '',
        user: info.user || '',
        model: info.model || '',
        venus: info.venus || '',
        kernel: info.kernel || '',
        uptimeText: formatDuration(info.uptimeSec),
        cpu: {
            usagePct: cpuUsagePct,
            ncpu,
            model: info.cpuModel || '',
            load: info.load || [0, 0, 0],
            runnable: info.runnable || '',
            level: cpuUsagePct >= 85 ? 'critical' : (cpuUsagePct >= 60 ? 'warning' : 'ok')
        },
        memory: {
            totalText: formatBytes(memTotalKb * 1024),
            usedText: formatBytes(memUsedKb * 1024),
            availableText: formatBytes(memAvailableKb * 1024),
            usedPct: memUsedPct,
            cachedText: formatBytes(((mem.Cached || 0) + (mem.Buffers || 0)) * 1024),
            swapText: swapTotalKb ? formatBytes(swapUsedKb * 1024) + ' of ' + formatBytes(swapTotalKb * 1024) : 'none',
            level: memUsedPct >= 85 ? 'critical' : (memUsedPct >= 70 ? 'warning' : 'ok')
        },
        temps: info.temps,
        disks,
        interfaces,
        tcp: {
            total: info.tcp.length,
            established: stateCounts.ESTABLISHED || 0,
            listen: stateCounts.LISTEN || 0,
            timeWait: stateCounts.TIME_WAIT || 0,
            other: info.tcp.length - (stateCounts.ESTABLISHED || 0) - (stateCounts.LISTEN || 0) - (stateCounts.TIME_WAIT || 0),
            listening,
            loopback: loopbackCount,
            connections: external.slice(0, 40),
            connectionsHidden: Math.max(0, external.length - 40)
        },
        processes: {
            count: processes.length,
            threads: threadCount,
            topCpu,
            topMem
        },
        services,
        warnings
    };
}

let state = flow.get(STATE_KEY) || { busySince: 0, view: null };
const nowTs = Date.now();

if (msg.topic === 'device-status-exec') {
    state.busySince = 0;
    state.view = buildView(parseOutput(msg.payload));
    // Written by "BMS watchdog" every 30 s.
    state.view.bmsWatchdog = flow.get('bmsWatchdogState') || null;
    state.error = '';
    flow.set(STATE_KEY, state);
    return [{ topic: 'device-status', payload: state.view }, null];
}

// Refresh request (dashboard button, auto-refresh, connect): one sampling run at a time.
if (state.busySince && nowTs - state.busySince < BUSY_TIMEOUT_MS) {
    return [state.view ? { topic: 'device-status', payload: state.view } : null, null];
}

state.busySince = nowTs;
flow.set(STATE_KEY, state);
return [
    state.view ? { topic: 'device-status', payload: state.view } : null,
    { topic: 'device-status-exec', payload: shellQuote(SCRIPT) }
];

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `30 BMS watchdog.js` and the embedded `func` for "BMS watchdog"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Keeps DVCC "Controlling BMS" pointed at the SerialBattery. After a reboot it was found empty
//   (com.victronenergy.system /ActiveBmsService = []), so the MultiPlus raised "BMS connection lost"
//   + "Low battery" and stayed in Passthru until the BMS was selected again by hand.
// How it works (every 30 s, via the dbus CLI in the exec node, works as user `nodered`):
// - reads /ActiveBmsService (system), /Settings/SystemSetup/BmsInstance (settings), the SerialBattery
//   /Connected, and the VE.Bus /State + BMS-lost / low-battery alarms
// - while a BMS is active, the current BmsInstance value is remembered in
//   /data/home/nodered/grid-control-config/bms-watchdog-good.txt (exact value, no format guessing)
// - when no BMS is active for 2 checks in a row while the SerialBattery is connected, the remembered
//   value is written back to /Settings/SystemSetup/BmsInstance (at most once per 5 minutes) and a GX
//   notification is raised
// - a VE.Bus system still in Passthru (state 8) with "BMS connection lost" while a BMS is active is only
//   reported (restarting VE.Bus automatically would interrupt the inverter)
// Inputs:
// - inject tick (any topic) -> start a check
// - topic `bms-watchdog-exec` (exec stdout) -> evaluate
// Outputs (2):
// - output 1 -> exec "Run BMS watchdog" (`sh -c <payload>`)
// - output 2 -> "Format GX notification" (msg.notification = { title, message, type })
// Flow context:
// - `bmsWatchdogState` (also shown on the Device page)
// Change notes:
// 1. Initial version.
// 2. Topic `bms-watchdog-force` (Driver page button) checks immediately and repairs on that check,
//    skipping the 2-check wait and the cooldown. Any other non-exec topic starts a normal check.
// ==========================

const GOOD_FILE = '/data/home/nodered/grid-control-config/bms-watchdog-good.txt';
const STATE_KEY = 'bmsWatchdogState';
const MISSING_CHECKS_BEFORE_REPAIR = 2;
const REPAIR_COOLDOWN_MS = 5 * 60 * 1000;
const NOTIFY_COOLDOWN_MS = 30 * 60 * 1000;
const PASSTHRU_GRACE_MS = 2 * 60 * 1000;
const BUSY_TIMEOUT_MS = 25000;
const NOTIFICATION_TITLE = 'BMS watchdog';

function shellQuote(text) {
    return "'" + String(text).replace(/'/g, "'\\''") + "'";
}

const READ_SCRIPT = [
    'F="' + GOOD_FILE + '"',
    'g() { dbus -y "$1" "$2" GetValue 2>/dev/null | sed "s/^value = //"; }',
    'B=$(dbus -y 2>/dev/null | grep -m 1 "^com.victronenergy.battery.tty")',
    'V=$(dbus -y 2>/dev/null | grep -m 1 "^com.victronenergy.vebus")',
    'echo "@@ACTIVE $(g com.victronenergy.system /ActiveBmsService)"',
    'echo "@@SETTING $(g com.victronenergy.settings /Settings/SystemSetup/BmsInstance)"',
    'echo "@@BATT $B"',
    '[ -n "$B" ] && echo "@@CONNECTED $(g "$B" /Connected)"',
    '[ -n "$V" ] && { echo "@@VEBUS $V"; echo "@@VSTATE $(g "$V" /State)"; echo "@@BMSLOST $(g "$V" /Alarms/BmsConnectionLost)"; echo "@@LOWBATT $(g "$V" /Alarms/LowBattery)"; }',
    'echo "@@GOOD $(head -n 1 "$F" 2>/dev/null)"',
    'true'
];

function buildSaveGoodScript(value) {
    return 'mkdir -p "' + GOOD_FILE.replace(/\/[^/]+$/, '') + '" && printf "%s\\n" ' + shellQuote(value) + ' > "' + GOOD_FILE + '" && echo "@@SAVED"';
}

// Writes the remembered value back with the same type it was read with:
// a number -> `%<n>` (dbus CLI integer syntax), a quoted string -> plain string argument.
function buildRepairScript(value) {
    const trimmed = String(value).trim();
    const argument = /^-?\d+$/.test(trimmed)
        ? '%' + trimmed
        : shellQuote(trimmed.replace(/^'(.*)'$/, '$1').replace(/^"(.*)"$/, '$1'));
    return 'dbus -y com.victronenergy.settings /Settings/SystemSetup/BmsInstance SetValue ' + argument + ' >/dev/null 2>&1; echo "@@WROTE $?"';
}

function isActiveBms(value) {
    const text = String(value || '').trim();
    return Boolean(text) && !['[]', "''", '""', 'None', '0', 'null'].includes(text);
}

function parse(rawText) {
    const values = {};
    String(rawText || '').split(/\r?\n/).forEach(line => {
        const match = line.match(/^@@([A-Z]+) ?(.*)$/);
        if (match) {
            values[match[1]] = match[2].trim();
        }
    });
    return values;
}

function notify(state, key, type, message, nowTs) {
    state.lastNotified = state.lastNotified || {};
    if (nowTs - (Number(state.lastNotified[key]) || 0) < NOTIFY_COOLDOWN_MS) {
        return null;
    }
    state.lastNotified[key] = nowTs;
    return { notification: { title: NOTIFICATION_TITLE, message, type }, payload: message };
}

function timeLabel(ts) {
    const date = new Date(ts);
    return String(date.getHours()).padStart(2, '0') + ':' + String(date.getMinutes()).padStart(2, '0');
}

const nowTs = Date.now();
let state = flow.get(STATE_KEY) || { missingCount: 0, busySince: 0, lastRepairAt: 0, passthruSince: 0 };

if (msg.topic !== 'bms-watchdog-exec') {
    // `bms-watchdog-force` (Driver page "Restore Controlling BMS now"): repair on this check,
    // without waiting for the second missing check or the cooldown.
    if (msg.topic === 'bms-watchdog-force') {
        state.forceRepair = true;
    }
    if (state.busySince && nowTs - state.busySince < BUSY_TIMEOUT_MS) {
        flow.set(STATE_KEY, state);
        return null;
    }
    state.busySince = nowTs;
    flow.set(STATE_KEY, state);
    return [{ topic: 'bms-watchdog-exec', bmsWatchdogStep: 'read', payload: shellQuote(READ_SCRIPT.join('\n')) }, null];
}

state.busySince = 0;
const step = msg.bmsWatchdogStep || 'read';
const values = parse(msg.payload);

// Results of a follow-up write: only record them, the next periodic read evaluates again.
if (step === 'save-good') {
    state.goodSavedAt = values.SAVED !== undefined ? nowTs : state.goodSavedAt;
    flow.set(STATE_KEY, state);
    return null;
}

if (step === 'repair') {
    const ok = values.WROTE === '0';
    state.lastRepairResult = ok ? 'written' : 'write failed (exit ' + (values.WROTE || '?') + ')';
    flow.set(STATE_KEY, state);
    node.status({ fill: ok ? 'yellow' : 'red', shape: 'dot', text: timeLabel(nowTs) + ' repair ' + state.lastRepairResult });
    return [null, ok ? null : notify(state, 'repair-failed', 'alarm', 'Could not restore Controlling BMS automatically. Select it in Settings > System setup > Charge control.', nowTs)];
}

const active = values.ACTIVE || '';
const setting = values.SETTING || '';
const good = values.GOOD || '';
const batteryService = values.BATT || '';
const batteryConnected = values.CONNECTED === '1';
const vebusState = values.VSTATE === undefined ? null : Number(values.VSTATE);
const bmsLost = Number(values.BMSLOST) || 0;
const lowBattery = Number(values.LOWBATT) || 0;
const activeOk = isActiveBms(active);

Object.assign(state, {
    checkedAt: new Date(nowTs).toISOString(),
    active,
    setting,
    good,
    batteryService,
    batteryConnected,
    vebusService: values.VEBUS || '',
    vebusState,
    bmsLost,
    lowBattery
});

const outputs = [null, null];
const forced = Boolean(state.forceRepair);
state.forceRepair = false;

if (activeOk) {
    state.missingCount = 0;
    state.status = 'ok';
    state.statusText = 'Active BMS ' + active + (forced ? ' - nothing to restore' : '');

    // Remember the working setting so it can be restored exactly.
    if (setting && setting !== good) {
        outputs[0] = { topic: 'bms-watchdog-exec', bmsWatchdogStep: 'save-good', payload: shellQuote(buildSaveGoodScript(setting)) };
        state.good = setting;
    }

    // Multi did not recover after the BMS came back.
    if (vebusState === 8 && bmsLost > 0) {
        state.passthruSince = state.passthruSince || nowTs;
        if (nowTs - state.passthruSince >= PASSTHRU_GRACE_MS) {
            state.status = 'warning';
            state.statusText = 'BMS active, but MultiPlus still in Passthru with "BMS connection lost" - restart the VE.Bus system';
            outputs[1] = notify(state, 'passthru', 'warning', state.statusText, nowTs);
        }
    }
    else {
        state.passthruSince = 0;
    }
}
else if (!batteryConnected) {
    state.missingCount = 0;
    state.status = 'waiting';
    state.statusText = batteryService ? 'SerialBattery not connected yet (' + batteryService + ')' : 'No SerialBattery service on D-Bus';
}
else {
    state.missingCount = (Number(state.missingCount) || 0) + 1;
    state.status = 'alarm';
    state.statusText = 'No active BMS although ' + batteryService + ' is connected (check ' + state.missingCount + ')';

    if (!good) {
        state.statusText += ' - no remembered setting yet, select Controlling BMS by hand once';
        outputs[1] = notify(state, 'no-good', 'alarm', 'No active BMS: select Controlling BMS in Settings > System setup > Charge control.', nowTs);
    }
    else if (setting === good) {
        state.statusText += ' - setting already correct, waiting for system calc';
        if (state.missingCount >= MISSING_CHECKS_BEFORE_REPAIR * 3) {
            outputs[1] = notify(state, 'stuck', 'alarm', 'No active BMS although Controlling BMS is set. Re-select it in Settings > System setup > Charge control.', nowTs);
        }
    }
    else if (forced || (state.missingCount >= MISSING_CHECKS_BEFORE_REPAIR && nowTs - (Number(state.lastRepairAt) || 0) >= REPAIR_COOLDOWN_MS)) {
        state.lastRepairAt = nowTs;
        state.lastRepairFrom = setting;
        state.statusText = 'Restoring Controlling BMS ' + (setting || '(empty)') + ' -> ' + good;
        outputs[0] = { topic: 'bms-watchdog-exec', bmsWatchdogStep: 'repair', payload: shellQuote(buildRepairScript(good)) };
        outputs[1] = notify(state, 'repair', 'warning', 'Controlling BMS was lost (' + (setting || 'empty') + '); restored automatically to the SerialBattery.', nowTs);
    }
}

flow.set(STATE_KEY, state);
node.status({
    fill: state.status === 'ok' ? 'green' : (state.status === 'waiting' ? 'grey' : (state.status === 'warning' ? 'yellow' : 'red')),
    shape: 'dot',
    text: timeLabel(nowTs) + ' ' + state.statusText
});
return outputs;

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `31 Driver checks dashboard.js` and the embedded `func` for "Driver checks dashboard"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - "Driver" dashboard page: every check used to diagnose the dbus-serialbattery driver, DVCC
//   "Controlling BMS" and the MultiPlus BMS alarms, plus the driver logs and a few safe controls.
// Checks (one exec run, read-only, works as user `nodered`):
// - serial devices, driver service (svstat, if permitted) and driver process + its uptime
// - all D-Bus values in ONE python call (instead of ~30 `dbus` CLI calls): SerialBattery values and
//   alarms, VE.Bus state / error / BMS alarms, system /ActiveBmsService, DVCC + BMS settings, and the
//   non-zero /Alarms of every Victron service
// - effective dbus-serialbattery config.ini (non-comment lines) and the BMS watchdog's remembered value
// - a timeline of the last samples (active BMS, setting, VE.Bus state, BMS-lost alarm) for the repair test
// Logs: tail of /var/log/<service>/current (or /data/log/...) through tai64nlocal; the log list is
//   discovered by the checks and only those paths can be read.
// Controls: refresh, run the BMS watchdog now, force-restore Controlling BMS (both via "BMS watchdog"),
//   clear the timeline. Root-only actions (restart driver, enable.sh) are shown as SSH commands.
// Inputs:
// - topic `driver-command` (dashboard): payload { action: 'refresh' | 'logs' | 'watchdog' | 'restore-bms'
//   | 'clear-timeline', log, lines }
// - topic `driver-exec` (exec stdout): script output with `@@` markers (msg.driverStep = checks | logs)
// - anything else -> refresh
// Outputs (3):
// - output 1 -> dashboard template (topic `driver-status`)
// - output 2 -> exec "Run driver checks" (`sh -c <payload>`)
// - output 3 -> "BMS watchdog" (topic bms-watchdog-tick | bms-watchdog-force)
// Change notes:
// 1. Initial version.
// 2. Display fixes: lists of objects (e.g. /AvailableBmsServices) are shown as JSON instead of
//    "[object Object]", D-Bus floats are rounded to 3 decimals.
// 3. Log folders that exist but are root-only (the default on Venus) are reported as `logDenied`
//    with their permissions, plus a health check; the page shows the root command to make them readable.
// ==========================

const STATE_KEY = 'driverDashboardState';
const CONFIG_PATH = '/data/apps/dbus-serialbattery/config.ini';
const GOOD_FILE = '/data/home/nodered/grid-control-config/bms-watchdog-good.txt';
const BUSY_TIMEOUT_MS = 30000;
const TIMELINE_LENGTH = 40;
const LOG_LINE_CHOICES = [50, 200, 500, 1000];
const VEBUS_STATES = {
    0: 'Off', 1: 'Low power', 2: 'Fault', 3: 'Bulk', 4: 'Absorption', 5: 'Float', 6: 'Storage', 7: 'Equalize',
    8: 'Passthru', 9: 'Inverting', 10: 'Power assist', 11: 'Power supply', 244: 'Sustain', 252: 'External control (ESS)'
};
const VEBUS_MODES = { 1: 'Charger only', 2: 'Inverter only', 3: 'On', 4: 'Off' };
const BATTERY_PATHS = [
    '/ProductName', '/CustomName', '/Connected', '/DeviceInstance', '/Soc', '/Dc/0/Voltage', '/Dc/0/Current', '/Dc/0/Power',
    '/Dc/0/Temperature', '/Info/MaxChargeCurrent', '/Info/MaxDischargeCurrent', '/Info/MaxChargeVoltage',
    '/System/MinCellVoltage', '/System/MaxCellVoltage', '/System/NrOfCellsPerBattery', '/InstalledCapacity',
    '/Io/AllowToCharge', '/Io/AllowToDischarge', '/Io/AllowToBalance', '/FirmwareVersion', '/HardwareVersion', '/Alarms'
];
const VEBUS_PATHS = [
    '/ProductName', '/State', '/Mode', '/VebusError', '/Dc/0/Voltage', '/Dc/0/Current',
    '/Alarms/LowBattery', '/Alarms/BmsConnectionLost', '/Alarms/HighTemperature', '/Alarms/Overload',
    '/Bms/BmsExpected', '/Bms/AllowToCharge', '/Bms/AllowToDischarge', '/Bms/Error'
];
const SYSTEM_PATHS = ['/ActiveBmsService', '/ActiveBatteryService', '/AvailableBmsServices', '/Dc/Battery/Soc', '/Control/MaxChargeCurrent'];
const SETTINGS_PATHS = [
    '/Settings/Services/Bol', '/Settings/SystemSetup/BmsInstance', '/Settings/SystemSetup/BatteryService',
    '/Settings/SystemSetup/MaxChargeCurrent'
];

function shellQuote(script) {
    return "'" + String(script).replace(/'/g, "'\\''") + "'";
}

const PYTHON = [
    'import json, sys',
    'try:',
    '    import dbus',
    'except Exception as error:',
    '    print("@@DBUSJSON " + json.dumps({"error": "python dbus module: %s" % error}))',
    '    sys.exit(0)',
    'BAT = ' + JSON.stringify(BATTERY_PATHS),
    'VEB = ' + JSON.stringify(VEBUS_PATHS),
    'SYS = ' + JSON.stringify(SYSTEM_PATHS),
    'SET = ' + JSON.stringify(SETTINGS_PATHS),
    'bus = dbus.SystemBus()',
    'def get(service, path):',
    '    try:',
    '        return bus.get_object(service, path, introspect=False).GetValue(dbus_interface="com.victronenergy.BusItem", timeout=3)',
    '    except Exception:',
    '        return None',
    'names = sorted(str(n) for n in bus.list_names() if str(n).startswith("com.victronenergy."))',
    'bat = next((n for n in names if n.startswith("com.victronenergy.battery.tty")), None)',
    'veb = next((n for n in names if n.startswith("com.victronenergy.vebus")), None)',
    'out = {"services": names, "battery": bat, "vebus": veb, "bat": {}, "veb": {}, "sys": {}, "set": {}, "alarms": {}}',
    'if bat:',
    '    out["bat"] = dict((p, get(bat, p)) for p in BAT)',
    'if veb:',
    '    out["veb"] = dict((p, get(veb, p)) for p in VEB)',
    'out["sys"] = dict((p, get("com.victronenergy.system", p)) for p in SYS)',
    'out["set"] = dict((p, get("com.victronenergy.settings", p)) for p in SET)',
    'for n in names:',
    '    alarms = get(n, "/Alarms")',
    '    if isinstance(alarms, dict):',
    '        active = dict((str(k), v) for k, v in alarms.items() if isinstance(v, (int, float)) and v)',
    '        if active:',
    '            out["alarms"][n] = active',
    'print("@@DBUSJSON " + json.dumps(out, default=str))'
].join('\n');

const CHECK_SCRIPT = [
    'echo "@@NOW $(date "+%Y-%m-%d %H:%M:%S")"',
    'echo "@@UPTIME $(cut -d" " -f1 /proc/uptime)"',
    'echo "@@USER $(id -un 2>/dev/null)"',
    'for d in /dev/ttyUSB* /dev/ttyACM*; do [ -e "$d" ] && echo "@@TTY $d"; done',
    'for s in /service/dbus-serialbattery.*; do [ -e "$s" ] && echo "@@SVC ${s##*/}|$(svstat "$s" 2>&1)"; done',
    // `[.]` keeps this script itself (whose command line contains the text) from matching.
    'for f in $(grep -la "dbus-serialbattery[.]py" /proc/[0-9]*/cmdline 2>/dev/null); do d=${f%/cmdline}; read -r st 2>/dev/null < "$d/stat" && echo "@@PROC $st"; printf "@@ARGS %s " "${d#/proc/}"; tr "\\000" " " 2>/dev/null < "$f"; echo; done',
    // Log folders are root-only by default: report "exists but not readable" separately.
    'for d in /var/log/dbus-serialbattery.* /var/log/serial-starter /var/log/dbus-aggregate-batteries* /data/log/dbus-serialbattery.*; do [ -e "$d" ] || continue; if [ -r "$d/current" ]; then echo "@@LOGDIR $d"; else echo "@@LOGDENIED $d|$(ls -ld "$d" 2>&1 | tr -s " ")"; fi; done',
    'if [ -r "' + CONFIG_PATH + '" ]; then grep -v -E "^[[:space:]]*([;#]|$)" "' + CONFIG_PATH + '" | sed "s/^/@@CFG /"; else echo "@@CFGERR not readable"; fi',
    'echo "@@GOOD $(head -n 1 "' + GOOD_FILE + '" 2>/dev/null)"',
    'PY=$(command -v python3 || command -v python)',
    'if [ -n "$PY" ]; then "$PY" - <<\'PYEOF\'',
    PYTHON,
    'PYEOF',
    'else echo "@@DBUSJSON {\\"error\\": \\"python not found\\"}"; fi',
    'true'
].join('\n');

function buildLogScript(logDir, lines) {
    return 'echo "@@LOGFILE ' + logDir + '/current"; '
        + 'tail -n ' + lines + ' "' + logDir + '/current" 2>&1 | { command -v tai64nlocal >/dev/null 2>&1 && tai64nlocal || cat; } | sed "s/^/@@L /"';
}

function toNumber(value) {
    if (value === null || value === undefined || Array.isArray(value) || value === '') {
        return null;
    }
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
}

function display(value) {
    if (value === null || value === undefined) {
        return '—';
    }
    if (Array.isArray(value)) {
        // e.g. /AvailableBmsServices is a list of objects
        return value.length ? value.map(item => (item && typeof item === 'object' ? JSON.stringify(item) : display(item))).join(', ') : '(empty)';
    }
    if (typeof value === 'object') {
        return JSON.stringify(value);
    }
    if (typeof value === 'number' && !Number.isInteger(value)) {
        // D-Bus floats arrive as 54.59999847412109
        return String(Math.round(value * 1000) / 1000);
    }
    return String(value);
}

function formatDuration(seconds) {
    const total = Math.max(0, Math.floor(Number(seconds) || 0));
    const days = Math.floor(total / 86400);
    const hours = Math.floor((total % 86400) / 3600);
    const minutes = Math.floor((total % 3600) / 60);
    return (days ? days + 'd ' : '') + (days || hours ? hours + 'h ' : '') + minutes + 'm ' + (total % 60) + 's';
}

function parseChecks(rawText) {
    const result = { ttys: [], services: [], processes: [], args: {}, logDirs: [], logDenied: [], config: [], configError: '', good: '', dbus: null };
    String(rawText || '').split(/\r?\n/).forEach(line => {
        const match = line.match(/^@@([A-Z]+) ?(.*)$/);
        if (!match) {
            return;
        }
        const value = match[2];
        switch (match[1]) {
            case 'NOW': result.now = value.trim(); break;
            case 'UPTIME': result.uptimeSec = Number(value.trim()) || 0; break;
            case 'USER': result.user = value.trim(); break;
            case 'TTY': result.ttys.push(value.trim()); break;
            case 'SVC': {
                const parts = value.split('|');
                result.services.push({ name: parts[0], status: parts.slice(1).join('|').replace(/^[^:]*:\s*/, '').trim() });
                break;
            }
            case 'PROC': {
                const close = value.lastIndexOf(')');
                const rest = value.substring(close + 2).split(' ');
                result.processes.push({ pid: Number(value.substring(0, value.indexOf('(')).trim()), startTicks: Number(rest[19]) || 0 });
                break;
            }
            case 'ARGS': {
                const parts = value.match(/^(\d+) (.*)$/);
                if (parts) {
                    result.args[Number(parts[1])] = parts[2].trim();
                }
                break;
            }
            case 'LOGDIR': result.logDirs.push(value.trim()); break;
            case 'LOGDENIED': {
                const parts = value.split('|');
                result.logDenied.push({ path: parts[0].trim(), detail: parts.slice(1).join('|').trim() });
                break;
            }
            case 'CFG': result.config.push(value.trim()); break;
            case 'CFGERR': result.configError = value.trim(); break;
            case 'GOOD': result.good = value.trim(); break;
            case 'DBUSJSON':
                try {
                    result.dbus = JSON.parse(value);
                }
                catch (error) {
                    result.dbus = { error: 'cannot parse D-Bus output: ' + error.message };
                }
                break;
            default:
                break;
        }
    });
    return result;
}

function check(name, level, detail) {
    return { name, level, detail };
}

function buildView(parsed, state) {
    const dbusData = parsed.dbus || { error: 'no D-Bus output' };
    const bat = dbusData.bat || {};
    const veb = dbusData.veb || {};
    const sys = dbusData.sys || {};
    const set = dbusData.set || {};
    const uptimeSec = parsed.uptimeSec || 0;

    // Driver process
    const processes = parsed.processes.map(proc => ({
        pid: proc.pid,
        args: parsed.args[proc.pid] || '',
        uptimeText: formatDuration(uptimeSec - proc.startTicks / 100),
        uptimeSec: uptimeSec - proc.startTicks / 100
    }));
    const driverProcess = processes[0] || null;

    // Config
    const configMap = {};
    const duplicates = [];
    parsed.config.forEach(line => {
        const kv = line.match(/^([A-Za-z0-9_]+)\s*=\s*(.*)$/);
        if (kv) {
            if (Object.prototype.hasOwnProperty.call(configMap, kv[1])) {
                duplicates.push(kv[1]);
            }
            configMap[kv[1]] = kv[2].trim();
        }
    });

    // Battery
    const minCell = toNumber(bat['/System/MinCellVoltage']);
    const maxCell = toNumber(bat['/System/MaxCellVoltage']);
    const cellSpreadMv = minCell !== null && maxCell !== null ? Math.round((maxCell - minCell) * 1000) : null;
    const batteryAlarms = bat['/Alarms'] && typeof bat['/Alarms'] === 'object' && !Array.isArray(bat['/Alarms'])
        ? Object.keys(bat['/Alarms']).filter(key => toNumber(bat['/Alarms'][key])).map(key => key + '=' + bat['/Alarms'][key])
        : [];

    // VE.Bus
    const vebusState = toNumber(veb['/State']);
    const vebusMode = toNumber(veb['/Mode']);
    const vebusError = toNumber(veb['/VebusError']);
    const bmsLost = toNumber(veb['/Alarms/BmsConnectionLost']) || 0;
    const lowBattery = toNumber(veb['/Alarms/LowBattery']) || 0;

    // System / settings
    const activeBms = sys['/ActiveBmsService'];
    const activeBmsOk = typeof activeBms === 'string' && activeBms.length > 0;
    const dvccOn = toNumber(set['/Settings/Services/Bol']) === 1;
    const bmsSetting = set['/Settings/SystemSetup/BmsInstance'];

    // Active alarms of all services
    const alarmList = [];
    Object.keys(dbusData.alarms || {}).forEach(service => {
        Object.keys(dbusData.alarms[service]).forEach(name => {
            const level = Number(dbusData.alarms[service][name]);
            alarmList.push({ service, name, level, levelText: level >= 2 ? 'alarm' : 'warning' });
        });
    });

    // svstat needs read access to the root-owned supervise folder; as `nodered` it usually reports
    // "unable to open ... access denied" - then the process check below is used instead.
    const svcRaw = parsed.services[0] || null;
    const svc = svcRaw && !/unable|denied|permission/i.test(svcRaw.status) ? svcRaw : null;
    const svcUp = svc ? /^up/.test(svc.status) : null;
    const svcSeconds = svc ? Number((svc.status.match(/(\d+) seconds/) || [])[1]) : null;
    const watchdog = flow.get('bmsWatchdogState') || null;

    const checks = [
        check('Serial port', parsed.ttys.length ? 'ok' : 'bad', parsed.ttys.join(', ') || 'no /dev/ttyUSB* or /dev/ttyACM*'),
        svc
            ? check('Driver service', svcUp ? (svcSeconds !== null && svcSeconds < 30 ? 'warn' : 'ok') : 'bad',
                svc.name + ': ' + svc.status + (svcUp && svcSeconds !== null && svcSeconds < 30 ? ' (recently restarted - watch whether it keeps restarting)' : ''))
            : check('Driver service', driverProcess ? 'info' : 'bad', svcRaw
                ? svcRaw.name + ': svstat needs root (' + svcRaw.status + '), using the process check'
                : (driverProcess ? 'no /service entry visible, using the process check' : 'no /service/dbus-serialbattery.*')),
        check('Driver process', driverProcess ? (driverProcess.uptimeSec < 30 ? 'warn' : 'ok') : 'bad',
            driverProcess ? 'pid ' + driverProcess.pid + ', running ' + driverProcess.uptimeText : 'dbus-serialbattery.py is not running'),
        check('BMS on D-Bus', dbusData.battery ? (toNumber(bat['/Connected']) === 1 ? 'ok' : 'bad') : 'bad',
            dbusData.battery ? dbusData.battery + ', Connected=' + display(bat['/Connected']) : (dbusData.error || 'no com.victronenergy.battery.tty* service')),
        check('BMS_TYPE in config.ini', configMap.BMS_TYPE ? 'ok' : 'warn',
            configMap.BMS_TYPE ? 'BMS_TYPE = ' + configMap.BMS_TYPE : (parsed.configError ? 'config.ini ' + parsed.configError : 'not set: the driver scans all BMS types (~1 min) after every boot')),
        check('config.ini duplicates', duplicates.length ? 'warn' : 'ok', duplicates.length ? 'duplicate keys: ' + duplicates.join(', ') : 'none'),
        check('DVCC', dvccOn ? 'ok' : 'bad', dvccOn ? 'on' : 'off or unknown (' + display(set['/Settings/Services/Bol']) + ')'),
        check('Controlling BMS / active BMS', activeBmsOk ? 'ok' : 'bad',
            'active: ' + display(activeBms) + ' | setting: ' + display(bmsSetting)),
        check('Watchdog remembered setting', parsed.good ? 'ok' : 'warn', parsed.good ? parsed.good : 'none yet (saved automatically while a BMS is active)'),
        check('MultiPlus state', vebusState === null ? 'warn' : (vebusState === 8 || vebusState === 2 ? 'bad' : 'ok'),
            vebusState === null ? 'no VE.Bus service' : vebusState + ' ' + (VEBUS_STATES[vebusState] || '') + ', mode ' + display(vebusMode) + ' ' + (VEBUS_MODES[vebusMode] || '')),
        check('MultiPlus BMS alarms', bmsLost || lowBattery ? 'bad' : 'ok',
            'BMS connection lost=' + bmsLost + ', low battery=' + lowBattery + ', VE.Bus error=' + display(vebusError)),
        check('Battery alarms', batteryAlarms.length ? 'bad' : 'ok', batteryAlarms.length ? batteryAlarms.join(', ') : 'none'),
        check('Cell balance', cellSpreadMv === null ? 'warn' : (cellSpreadMv > 100 ? 'bad' : (cellSpreadMv > 40 ? 'warn' : 'ok')),
            cellSpreadMv === null ? 'no cell data' : cellSpreadMv + ' mV (min ' + minCell + ' V / max ' + maxCell + ' V)'),
        check('Active alarms (all devices)', alarmList.length ? 'bad' : 'ok', alarmList.length ? alarmList.length + ' active' : 'none'),
        check('Driver logs readable', parsed.logDenied.length ? 'warn' : (parsed.logDirs.length ? 'ok' : 'warn'),
            parsed.logDenied.length
                ? parsed.logDenied.map(item => item.path).join(', ') + ' exist but are root-only - see "Driver logs" below'
                : (parsed.logDirs.length ? parsed.logDirs.join(', ') : 'no driver log folders found'))
    ];
    const worst = checks.some(item => item.level === 'bad') ? 'bad' : (checks.some(item => item.level === 'warn') ? 'warn' : 'ok');

    // Timeline sample (repair test monitor)
    const sample = {
        time: (parsed.now || '').substring(11, 19),
        active: display(activeBms),
        setting: display(bmsSetting),
        vebusState: vebusState === null ? '—' : vebusState + ' ' + (VEBUS_STATES[vebusState] || ''),
        bmsLost,
        lowBattery,
        ok: activeBmsOk && vebusState !== 8 && !bmsLost
    };
    state.timeline = (state.timeline || []).concat([sample]).slice(-TIMELINE_LENGTH);

    return {
        updatedAt: new Date().toISOString(),
        sampledAt: parsed.now || '',
        user: parsed.user || '',
        overall: worst,
        checks,
        battery: {
            service: dbusData.battery || '',
            rows: BATTERY_PATHS.filter(path => path !== '/Alarms').map(path => ({ path, value: display(bat[path]) })),
            cellSpreadMv
        },
        driver: {
            service: svcRaw,
            processes,
            ttys: parsed.ttys,
            config: parsed.config,
            configError: parsed.configError
        },
        system: {
            rows: SYSTEM_PATHS.map(path => ({ path, value: display(sys[path]) }))
                .concat(SETTINGS_PATHS.map(path => ({ path, value: display(set[path]) })))
        },
        vebus: {
            service: dbusData.vebus || '',
            rows: VEBUS_PATHS.map(path => {
                const value = veb[path];
                let text = display(value);
                if (path === '/State' && toNumber(value) !== null) {
                    text += ' (' + (VEBUS_STATES[toNumber(value)] || '?') + ')';
                }
                if (path === '/Mode' && toNumber(value) !== null) {
                    text += ' (' + (VEBUS_MODES[toNumber(value)] || '?') + ')';
                }
                return { path, value: text };
            })
        },
        alarms: alarmList,
        watchdog,
        good: parsed.good,
        timeline: state.timeline.slice().reverse(),
        logDirs: parsed.logDirs,
        logDenied: parsed.logDenied,
        log: state.log || null,
        dbusError: dbusData.error || '',
        logLineChoices: LOG_LINE_CHOICES
    };
}

let state = flow.get(STATE_KEY) || { busySince: 0, timeline: [], logDirs: [], log: null, view: null };
const nowTs = Date.now();

function emit(execMsg, watchdogMsg) {
    flow.set(STATE_KEY, state);
    const view = state.view ? Object.assign({}, state.view, { log: state.log, busy: Boolean(state.busySince) }) : null;
    return [view ? { topic: 'driver-status', payload: view } : null, execMsg || null, watchdogMsg || null];
}

if (msg.topic === 'driver-exec') {
    state.busySince = 0;
    if (msg.driverStep === 'logs') {
        const lines = [];
        let file = '';
        String(msg.payload || '').split(/\r?\n/).forEach(line => {
            if (line.startsWith('@@LOGFILE ')) {
                file = line.substring(10).trim();
            }
            else if (line.startsWith('@@L ')) {
                lines.push(line.substring(4));
            }
            else if (line === '@@L') {
                lines.push('');
            }
        });
        state.log = { file, text: lines.join('\n') || '(empty)', lineCount: lines.length, loadedAt: new Date().toISOString() };
        return emit();
    }

    const parsed = parseChecks(msg.payload);
    state.logDirs = parsed.logDirs;
    state.view = buildView(parsed, state);
    return emit();
}

const command = msg.topic === 'driver-command' && msg.payload && typeof msg.payload === 'object' ? msg.payload : { action: 'refresh' };
const action = String(command.action || 'refresh');

if (action === 'clear-timeline') {
    state.timeline = [];
    if (state.view) {
        state.view.timeline = [];
    }
    return emit();
}

if (action === 'watchdog' || action === 'restore-bms') {
    // The watchdog does the work; refresh the checks a bit later from the dashboard.
    return emit(null, { topic: action === 'restore-bms' ? 'bms-watchdog-force' : 'bms-watchdog-tick' });
}

if (state.busySince && nowTs - state.busySince < BUSY_TIMEOUT_MS) {
    return emit();
}

if (action === 'logs') {
    const logDir = String(command.log || '');
    const lines = LOG_LINE_CHOICES.includes(Number(command.lines)) ? Number(command.lines) : LOG_LINE_CHOICES[1];
    if (!(state.logDirs || []).includes(logDir)) {
        state.log = { file: logDir, text: 'Unknown log - refresh the checks first.', lineCount: 0, loadedAt: new Date().toISOString() };
        return emit();
    }
    state.busySince = nowTs;
    return emit({ topic: 'driver-exec', driverStep: 'logs', payload: shellQuote(buildLogScript(logDir, lines)) });
}

state.busySince = nowTs;
return emit({ topic: 'driver-exec', driverStep: 'checks', payload: shellQuote(CHECK_SCRIPT) });

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `33 MCP page.js` and the embedded `func` for "MCP page"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Manages the MCP access token and builds the "Agent (MCP)" dashboard page: endpoint URLs,
//   token, ready-to-paste client configuration, tool list and the latest agent calls.
// Token:
// - /data/home/nodered/grid-control-config/mcp-token.txt (48 hex chars from /dev/urandom, mode 600)
// - created automatically on first start; `regenerate` replaces it, `disable` deletes it
//   (the MCP server then answers 503); `enable` creates a new one
// - kept in flow `mcpToken` for "MCP server"
// URLs:
// - built from the GX LAN addresses and listening ports reported by the Device page
//   (flow deviceStatusState); 1881 = Node-RED HTTPS, 1880 = Node-RED HTTP (if reachable on the LAN)
// Inputs:
// - inject on start (any topic) / topic `mcp-command` { action: 'refresh' | 'regenerate' | 'disable' | 'enable' }
// - topic `mcp-exec` (exec stdout) with msg.mcpStep = load | regenerate | disable
// Outputs (2):
// - output 1 -> dashboard template (topic `mcp-page`)
// - output 2 -> exec "MCP token" (`sh -c <payload>`)
// Change notes:
// 1. Initial version.
// 2. `load` keeps an existing token (the `||` needed braces), token generation falls back to kernel
//    random UUIDs when `od` is not usable, and a failure is shown on the page (`tokenError`).
// 3. `https://venus.local:1881/mcp` is always the first endpoint (the GX certificate is issued to
//    venus.local; IP addresses fail certificate name checks in Node-based clients).
// ==========================

const TOKEN_FILE = '/data/home/nodered/grid-control-config/mcp-token.txt';
const MCP_PATH = 'mcp';
// Keep in sync with the TOOLS list in "32 MCP server.js".
const TOOL_SUMMARY = [
    { name: 'get_system_overview', text: 'window, battery V / Ah, grid / AC / PV power, setpoint, charge current, protections' },
    { name: 'get_capacity_tariff', text: 'season, tier, kWh today, left today, peak hour, month tier' },
    { name: 'get_energy_today', text: 'hourly grid / AC / solar Wh for today' },
    { name: 'get_solar_forecast', text: 'today\'s forecast and hourly adjusted forecast' },
    { name: 'get_battery_driver_status', text: 'driver / BMS / DVCC / MultiPlus health checks and alarms (+ refresh)' },
    { name: 'get_device_status', text: 'CPU, memory, disks, services, processes, network (+ refresh)' },
    { name: 'get_bms_watchdog', text: 'Controlling BMS watchdog state' },
    { name: 'get_settings', text: 'HV / grid support / force charge settings and constants overrides' },
    { name: 'list_backups', text: 'backups on the device and disk space' }
];

function shellQuote(script) {
    return "'" + String(script).replace(/'/g, "'\\''") + "'";
}

// 48 hex chars from /dev/urandom; if `od` behaves differently (BusyBox builds vary) fall back to two
// kernel random UUIDs (64 hex chars). Errors are reported with @@ERR.
const GENERATE = 'mkdir -p "' + TOKEN_FILE.replace(/\/[^/]+$/, '') + '" 2>/dev/null; '
    + 'T=$(head -c 24 /dev/urandom 2>/dev/null | od -An -tx1 2>/dev/null | tr -d " \\n"); '
    + '[ ${#T} -ge 32 ] || T=$(cat /proc/sys/kernel/random/uuid /proc/sys/kernel/random/uuid 2>/dev/null | tr -d -- "-\\n"); '
    + '(umask 077; printf "%s" "$T" > "' + TOKEN_FILE + '") 2>/dev/null || echo "@@ERR cannot write ' + TOKEN_FILE + ' as $(id -un)"';
const SCRIPTS = {
    // braces matter: without them `a || b && c` would regenerate the token on every load
    load: '[ -s "' + TOKEN_FILE + '" ] || { ' + GENERATE + '; }; echo "@@TOKEN $(cat "' + TOKEN_FILE + '" 2>/dev/null)"',
    regenerate: GENERATE + '; echo "@@TOKEN $(cat "' + TOKEN_FILE + '" 2>/dev/null)"',
    disable: 'rm -f "' + TOKEN_FILE + '"; echo "@@TOKEN "'
};

function buildEndpoints() {
    const device = flow.get('deviceStatusState');
    const view = device && device.view;
    const ips = [];
    if (view && Array.isArray(view.interfaces)) {
        view.interfaces.forEach(iface => {
            String(iface.ips || '').split(',').forEach(cidr => {
                const ip = cidr.trim().split('/')[0];
                if (ip && !/^127\.|^169\.254\./.test(ip)) {
                    ips.push({ ip, iface: iface.name });
                }
            });
        });
    }
    const listening = view && view.tcp && Array.isArray(view.tcp.listening) ? view.tcp.listening : [];
    const listensOnLan = port => listening.some(entry => entry.port === port
        && entry.addresses.some(address => !/^127\.|^::1\b/.test(address)));
    const known = listening.length > 0;
    // The GX certificate is issued to venus.local (no IP in it), so this is the address Node-based
    // clients such as Claude Code can verify (with NODE_EXTRA_CA_CERTS); always listed first.
    const endpoints = [{
        url: 'https://venus.local:1881/' + MCP_PATH,
        iface: 'mDNS',
        kind: 'https',
        note: 'Recommended on the home network: matches the GX certificate (venus.local)'
    }];

    ips.forEach(item => {
        if (!known || listensOnLan(1881)) {
            endpoints.push({ url: 'https://' + item.ip + ':1881/' + MCP_PATH, iface: item.iface, kind: 'https', note: 'Node-RED HTTPS by IP (curl -k works; the certificate name does not match an IP)' });
        }
        if (listensOnLan(1880)) {
            endpoints.push({ url: 'http://' + item.ip + ':1880/' + MCP_PATH, iface: item.iface, kind: 'http', note: 'Node-RED HTTP (no TLS - LAN only)' });
        }
    });

    return { endpoints, host: view ? view.host : '', sampledAt: view ? view.sampledAt : '', deviceKnown: Boolean(view) };
}

function emit(execMsg) {
    const token = String(flow.get('mcpToken') || '');
    const calls = (flow.get('mcpState') || {}).calls || [];
    const page = Object.assign({
        enabled: Boolean(token),
        token,
        tokenError: flow.get('mcpTokenError') || '',
        tokenFile: TOKEN_FILE,
        path: MCP_PATH,
        tools: TOOL_SUMMARY,
        calls,
        updatedAt: new Date().toISOString()
    }, buildEndpoints());
    return [{ topic: 'mcp-page', payload: page }, execMsg || null];
}

if (msg.topic === 'mcp-exec') {
    const output = String(msg.payload || '');
    const match = output.match(/@@TOKEN ?([0-9a-fA-F]*)/);
    const errorMatch = output.match(/@@ERR (.*)/);
    flow.set('mcpToken', match ? match[1] : '');
    flow.set('mcpTokenError', msg.mcpStep !== 'disable' && !(match && match[1])
        ? 'Token could not be created' + (errorMatch ? ': ' + errorMatch[1] : (output.trim() ? ' (output: ' + output.trim().substring(0, 200) + ')' : ' (no output from the exec node)'))
        : '');
    node.status({ fill: match && match[1] ? 'green' : 'grey', shape: 'dot', text: match && match[1] ? 'MCP enabled' : 'MCP disabled' });
    return emit();
}

const action = msg.topic === 'mcp-command' && msg.payload && msg.payload.action ? String(msg.payload.action) : 'load';

if (action === 'refresh') {
    return emit();
}

const step = action === 'regenerate' || action === 'enable' ? 'regenerate' : (action === 'disable' ? 'disable' : 'load');
return emit({ topic: 'mcp-exec', mcpStep: step, payload: shellQuote(SCRIPTS[step]) });

// ==========================
// LOGIC SUMMARY / CHANGE NOTES
// ==========================
// Sync rule:
// - `32 MCP server.js` and the embedded `func` for "MCP server"
//   in `flows.json` must always stay synchronized.
// Purpose:
// - Model Context Protocol (MCP) server so an AI agent (e.g. Claude Code) can read the system state.
// - Transport: MCP "Streamable HTTP" with plain JSON responses: `POST <node-red>/mcp` carries one
//   JSON-RPC 2.0 request (or a batch); `GET`/`DELETE /mcp` -> 405 (no server-initiated stream).
// - Methods: initialize, notifications/* (202), ping, tools/list, tools/call.
// - All tools are READ-ONLY. They return the latest data from flow context; the driver / device tools
//   also trigger a background refresh of those pages (call again a few seconds later for fresh data).
// Security:
// - every request needs the token from /data/home/nodered/grid-control-config/mcp-token.txt
//   (flow `mcpToken`, managed by "MCP page"): `Authorization: Bearer <token>` or `X-MCP-Token: <token>`
//   (the latter for setups where Node-RED HTTP basic auth already uses the Authorization header)
// - no token configured -> 503 (server disabled); wrong token -> 401
// - a browser `Origin` that does not match the Host is rejected (DNS-rebinding protection)
// Inputs:
// - msg from "POST /mcp" / "GET /mcp" (http in)
// Outputs (3):
// - output 1 -> http response
// - output 2 -> "Build device status" (refresh trigger)
// - output 3 -> "Driver checks dashboard" (refresh trigger)
// Flow context:
// - reads dashboardControllerTrace, dailySummary, dashboardLiveHour, solarForecastToday,
//   deviceStatusState, driverDashboardState, bmsWatchdogState, highVoltageSettings,
//   controllerConstantsOverrides, backupDashboardState, mcpToken
// - writes mcpState.calls (last calls, shown on the "Agent (MCP)" page)
// Change notes:
// 1. Initial version.
// 2. The call log uses X-Forwarded-For / X-Real-IP (Venus proxies Node-RED, so req.ip is 127.0.0.1).
// ==========================

const SERVER_NAME = 'victron-grid-control';
const SERVER_VERSION = '1.0.0';
const SUPPORTED_VERSIONS = ['2025-06-18', '2025-03-26', '2024-11-05'];
const MAX_CALL_LOG = 30;
const INSTRUCTIONS = [
    'Victron ESS on a Cerbo GX (Venus OS) controlled by Node-RED for Norwegian capacity-based grid tariffs.',
    'Battery: 14S NMC pack with a JBD BMS read by the dbus-serialbattery driver; inverter/charger: MultiPlus-II 48/5000.',
    'The controller holds the ESS grid setpoint at a season plan (summer tier 1 <= 2 kW, winter tier 2 <= 5 kW; night hours billed at 70 %),',
    'charges the battery in night/morning windows and protects against high voltage and grid export.',
    'All tools are read-only. Start with get_system_overview; use get_battery_driver_status when something looks wrong with the battery/BMS.'
].join(' ');

const NO_ARGS = { type: 'object', properties: {}, additionalProperties: false };
const REFRESH_ARGS = {
    type: 'object',
    properties: { refresh: { type: 'boolean', description: 'Also trigger a fresh check in the background (default true). Call again after ~5 s to read it.' } },
    additionalProperties: false
};

function ageSeconds(isoOrTs) {
    const ts = typeof isoOrTs === 'number' ? isoOrTs : Date.parse(isoOrTs || '');
    return Number.isFinite(ts) ? Math.round((Date.now() - ts) / 1000) : null;
}

function pick(source, keys) {
    const out = {};
    keys.forEach(key => {
        if (source && source[key] !== undefined) {
            out[key] = source[key];
        }
    });
    return out;
}

const TOOLS = [
    {
        name: 'get_system_overview',
        title: 'System overview',
        description: 'Live controller state: active window, battery voltage and consumed Ah, grid / AC load / PV power, ESS grid setpoint, DVCC charge current, VE.Bus input current limit, protections (high voltage, export guard, force charge, manual discharge) and active limit flags.',
        inputSchema: NO_ARGS,
        run() {
            const trace = flow.get('dashboardControllerTrace');
            if (!trace) {
                return { available: false, note: 'No controller trace yet (Node-RED just started?).' };
            }
            return Object.assign({ ageSeconds: ageSeconds(trace.timestamp) }, pick(trace, [
                'timestamp', 'window', 'batteryVoltage', 'consumedAhDeficit', 'storedGridPowerW', 'gridPowerSignedW',
                'storedAcLoadPowerW', 'storedPvChargerPowerW', 'solarGenerationW', 'baseScheduleSetpoint', 'finalGridSetpoint',
                'finalChargeCurrent', 'currentChargingPowerW', 'gridCurrentLimitA', 'voltageLimitActive', 'exportGuard',
                'forceChargeEnabled', 'forceChargeLimiterActive', 'effectiveForceChargeGridW', 'manualDischarge',
                'gridSupportMode', 'adaptiveGridSupportActive', 'adaptiveGridSupportW', 'gridRestoreAhNeeded',
                'forecastRestoreAh', 'boostActive', 'limitFlags'
            ]));
        }
    },
    {
        name: 'get_capacity_tariff',
        title: 'Capacity tariff status',
        description: 'Active tariff season (summer/winter) and tier, both season profiles (setpoints and safe grid current), grid import today, energy left today at the season plan, today\'s billable peak hour and the month\'s top-3 day average and resulting tier.',
        inputSchema: NO_ARGS,
        run() {
            const trace = flow.get('dashboardControllerTrace');
            return trace && trace.tariff
                ? Object.assign({ ageSeconds: ageSeconds(trace.timestamp) }, trace.tariff)
                : { available: false, note: 'No tariff data in the controller trace yet.' };
        }
    },
    {
        name: 'get_energy_today',
        title: 'Energy today',
        description: 'Hourly grid import, AC load and solar Wh for today (completed hours plus the live hour) and the day totals.',
        inputSchema: NO_ARGS,
        run() {
            const summary = flow.get('dailySummary') || { dateKey: '', hours: [] };
            const live = flow.get('dashboardLiveHour') || null;
            const hours = (summary.hours || []).map(row => pick(row, ['hour', 'gridWh', 'acWh', 'solarWh']));
            if (live && live.hourKey) {
                hours.push({ hour: live.hourKey.substring(11, 13) + ':00 (live)', gridWh: Math.round(live.gridWh || 0), acWh: Math.round(live.acWh || 0), solarWh: Math.round(live.solarWh || 0) });
            }
            const total = key => hours.reduce((sum, row) => sum + (Number(row[key]) || 0), 0);
            return { date: summary.dateKey, hours, totals: { gridWh: total('gridWh'), acWh: total('acWh'), solarWh: total('solarWh') } };
        }
    },
    {
        name: 'get_solar_forecast',
        title: 'Solar forecast',
        description: 'Today\'s solar forecast summary (energy, peak, condition) and the shade-adjusted hourly forecast.',
        inputSchema: NO_ARGS,
        run() {
            const today = flow.get('solarForecastToday') || null;
            const adjusted = flow.get('solarForecastAdjusted') || null;
            return { today, hourlyAdjustedW: adjusted && adjusted.adjustedResult ? adjusted.adjustedResult : null };
        }
    },
    {
        name: 'get_battery_driver_status',
        title: 'Battery driver / BMS / MultiPlus status',
        description: 'Health checks of the dbus-serialbattery driver, the BMS (SoC, cell voltages, charge/discharge limits, alarms), DVCC Controlling BMS, the MultiPlus state and BMS alarms, and all active alarms of every device. Also triggers a fresh check.',
        inputSchema: REFRESH_ARGS,
        refreshOutput: 3,
        run() {
            const state = flow.get('driverDashboardState');
            const view = state && state.view;
            if (!view) {
                return { available: false, note: 'No driver check yet - a check was triggered, call again in ~5 s.' };
            }
            return Object.assign({ ageSeconds: ageSeconds(view.updatedAt) }, pick(view, [
                'sampledAt', 'overall', 'checks', 'battery', 'vebus', 'system', 'alarms', 'watchdog', 'good', 'logDirs', 'logDenied'
            ]), { driver: view.driver ? pick(view.driver, ['service', 'processes', 'ttys', 'config']) : null });
        }
    },
    {
        name: 'get_device_status',
        title: 'GX device status',
        description: 'Cerbo GX health: CPU, load, memory, disks, temperature, uptime, Venus OS version, key services, top processes, network interfaces, listening ports and connections, warnings. Also triggers a fresh sample.',
        inputSchema: REFRESH_ARGS,
        refreshOutput: 2,
        run() {
            const state = flow.get('deviceStatusState');
            const view = state && state.view;
            if (!view) {
                return { available: false, note: 'No device sample yet - a sample was triggered, call again in ~5 s.' };
            }
            return Object.assign({ ageSeconds: ageSeconds(view.updatedAt) }, view);
        }
    },
    {
        name: 'get_bms_watchdog',
        title: 'BMS watchdog',
        description: 'State of the BMS watchdog that restores DVCC "Controlling BMS" after it is lost: active BMS, setting, remembered value, MultiPlus state, BMS-lost alarm, last repair.',
        inputSchema: NO_ARGS,
        run() {
            const state = flow.get('bmsWatchdogState');
            return state ? Object.assign({ ageSeconds: ageSeconds(state.checkedAt) }, state) : { available: false, note: 'Watchdog has not run yet (every 30 s).' };
        }
    },
    {
        name: 'get_settings',
        title: 'Controller settings',
        description: 'High-voltage protection / grid support / force charge / export guard settings and the controller constants overrides (tariff season dates, tiers, limits).',
        inputSchema: NO_ARGS,
        run() {
            return {
                highVoltageSettings: flow.get('highVoltageSettings') || null,
                controllerConstantsOverrides: flow.get('controllerConstantsOverrides') || {}
            };
        }
    },
    {
        name: 'list_backups',
        title: 'Backups',
        description: 'Backups stored on the device (name, date, size, kind) and the disk space.',
        inputSchema: NO_ARGS,
        run() {
            const state = flow.get('backupDashboardState') || {};
            return { backups: state.backups || [], disk: state.disk || null, lastResult: state.result ? pick(state.result, ['action', 'ok', 'message', 'at']) : null };
        }
    }
];

function rpcResult(id, result) {
    return { jsonrpc: '2.0', id, result };
}

function rpcError(id, code, message) {
    return { jsonrpc: '2.0', id: id === undefined ? null : id, error: { code, message } };
}

function respond(statusCode, body, extraHeaders) {
    msg.statusCode = statusCode;
    msg.headers = Object.assign({ 'Content-Type': 'application/json', 'Cache-Control': 'no-store' }, extraHeaders || {});
    msg.payload = body === undefined ? '' : body;
    return msg;
}

function logCall(entry) {
    const state = flow.get('mcpState') || { calls: [] };
    state.calls = [Object.assign({ at: new Date().toISOString() }, entry)].concat(state.calls || []).slice(0, MAX_CALL_LOG);
    state.lastCallAt = state.calls[0].at;
    flow.set('mcpState', state);
}

const req = msg.req || {};
const headers = req.headers || {};
const method = String(req.method || 'POST').toUpperCase();
// Venus OS serves Node-RED through a local HTTPS proxy, so req.ip is 127.0.0.1; prefer the forwarded client.
const forwardedFor = String(headers['x-forwarded-for'] || headers['x-real-ip'] || '').split(',')[0].trim();
const clientIp = String(forwardedFor || req.ip || (req.connection && req.connection.remoteAddress) || '').replace(/^::ffff:/, '');

if (method !== 'POST') {
    return [respond(405, { error: 'Use POST with a JSON-RPC body (MCP Streamable HTTP, JSON responses only).' }, { Allow: 'POST' }), null, null];
}

// DNS-rebinding protection: a browser request from another site carries a foreign Origin.
if (headers.origin) {
    // (no `URL` in the function sandbox)
    const originMatch = String(headers.origin).match(/^[a-z][a-z0-9+.-]*:\/\/([^/?#]+)/i);
    const originHost = originMatch ? originMatch[1].toLowerCase() : '';
    if (!originHost || originHost !== String(headers.host || '').toLowerCase()) {
        logCall({ ip: clientIp, method: '-', ok: false, detail: 'rejected origin ' + headers.origin });
        return [respond(403, rpcError(null, -32000, 'Origin not allowed')), null, null];
    }
}

const token = String(flow.get('mcpToken') || '').trim();
if (!token) {
    return [respond(503, rpcError(null, -32000, 'MCP server is disabled (no token). Enable it on the Agent (MCP) dashboard page.')), null, null];
}

const bearer = String(headers.authorization || '').match(/^Bearer\s+(.+)$/i);
const presented = String(headers['x-mcp-token'] || (bearer ? bearer[1] : '')).trim();
if (presented !== token) {
    logCall({ ip: clientIp, method: '-', ok: false, detail: presented ? 'wrong token' : 'missing token' });
    return [respond(401, rpcError(null, -32001, 'Unauthorized: send Authorization: Bearer <token> or X-MCP-Token: <token>')), null, null];
}

const body = msg.payload;
if (!body || typeof body !== 'object') {
    return [respond(400, rpcError(null, -32700, 'Parse error: expected a JSON-RPC object')), null, null];
}

const refreshOutputs = { 2: null, 3: null };

function handle(request) {
    if (!request || typeof request !== 'object' || request.jsonrpc !== '2.0' || typeof request.method !== 'string') {
        return rpcError(request && request.id, -32600, 'Invalid request');
    }
    const isNotification = request.id === undefined || request.id === null;
    const params = request.params || {};

    if (isNotification) {
        logCall({ ip: clientIp, method: request.method, ok: true });
        return null;
    }

    switch (request.method) {
        case 'initialize': {
            const requested = String(params.protocolVersion || '');
            const clientInfo = params.clientInfo ? (params.clientInfo.name || '') + ' ' + (params.clientInfo.version || '') : '';
            logCall({ ip: clientIp, method: 'initialize', ok: true, detail: clientInfo.trim() });
            return rpcResult(request.id, {
                protocolVersion: SUPPORTED_VERSIONS.includes(requested) ? requested : SUPPORTED_VERSIONS[0],
                capabilities: { tools: { listChanged: false } },
                serverInfo: { name: SERVER_NAME, title: 'Victron grid control (Cerbo GX)', version: SERVER_VERSION },
                instructions: INSTRUCTIONS
            });
        }
        case 'ping':
            return rpcResult(request.id, {});
        case 'tools/list':
            logCall({ ip: clientIp, method: 'tools/list', ok: true });
            return rpcResult(request.id, {
                tools: TOOLS.map(tool => ({
                    name: tool.name,
                    title: tool.title,
                    description: tool.description,
                    inputSchema: tool.inputSchema,
                    annotations: { readOnlyHint: true, openWorldHint: false }
                }))
            });
        case 'tools/call': {
            const tool = TOOLS.find(item => item.name === params.name);
            if (!tool) {
                logCall({ ip: clientIp, method: 'tools/call', tool: String(params.name || ''), ok: false, detail: 'unknown tool' });
                return rpcError(request.id, -32602, 'Unknown tool: ' + params.name);
            }
            const args = params.arguments || {};
            if (tool.refreshOutput && args.refresh !== false) {
                refreshOutputs[tool.refreshOutput] = tool.refreshOutput === 2
                    ? { topic: 'device-status-command', payload: { action: 'refresh' } }
                    : { topic: 'driver-command', payload: { action: 'refresh' } };
            }
            try {
                const data = tool.run(args);
                logCall({ ip: clientIp, method: 'tools/call', tool: tool.name, ok: true });
                return rpcResult(request.id, { content: [{ type: 'text', text: JSON.stringify(data, null, 2) }], isError: false });
            }
            catch (error) {
                logCall({ ip: clientIp, method: 'tools/call', tool: tool.name, ok: false, detail: error.message });
                return rpcResult(request.id, { content: [{ type: 'text', text: 'Tool failed: ' + error.message }], isError: true });
            }
        }
        default:
            logCall({ ip: clientIp, method: request.method, ok: false, detail: 'method not found' });
            return rpcError(request.id, -32601, 'Method not found: ' + request.method);
    }
}

let responseBody;
if (Array.isArray(body)) {
    const responses = body.map(handle).filter(Boolean);
    responseBody = responses.length ? responses : undefined;
}
else {
    responseBody = handle(body) || undefined;
}

return [
    responseBody === undefined ? respond(202) : respond(200, responseBody),
    refreshOutputs[2],
    refreshOutputs[3]
];
